./jev/frame.ts'\nimport type { EgoContext, JudgeSettings, RawConfig, ResolvedConfig, SubprocessService, ToolExec, WebServerLike, BrowserLink, CdpMode, LightpandaLink } from './types.ts'\n\nexport const name = 'dsh-browser-cdp'\n// Platform-aware host services: the web shell exposes `webServer`, other Web\n// hosts expose `httpServer`. To keep activation platform-agnostic (TUI /\n// headless hosts have neither), neither is a required inject �?the /api/bcdp/*\n// watch routes are registered opportunistically via ctx.get('webServer') and\n// guarded, so a GUI-less host is a safe no-op. The bcdp_* tools depend only on\n// tools + subprocess, present in every host.\nexport const inject = ['tools', 'subprocess', 'settings']\n// Schemastery schema for the composition entry and the declarative settings\n// page. Re-exported from config.ts so the cordis loader validates the\n// composition layer and (0.1.7) projects the `.volatile()` fields into the\n// auto-generated settings form �?no registration call involved.\nexport const Config = ConfigSchema\n\n/**\n * defineTool's option type recurses through schemastery's `InferObject` and\n * trips TS2321 (excessive stack depth). The option shapes are proven by the\n * original JS, so we cast through `any` at the call sites instead of\n * instantiating the recursive generic.\n */\ntype DefineToolOpts = any\ntype ToolHandle = ReturnType<typeof defineTool>\n\n// ── constants ───────────────────────────────────────────────────────────────\n/** Vendored ego-linux CLI shipped inside this plugin (runtime/ego-linux/bin/). */\nconst VENDORED_EGO_BIN = fileURLToPath(\n  new URL('../runtime/ego-linux/bin/ego-browser.mjs', import.meta.url),\n)\nconst DEFAULT_EGO_BIN = VENDORED_EGO_BIN\n// DEFAULT_SPACE + AUTO_SPACE_SENTINEL now come from ./config.ts so the schema\n// default, resolveConfig fold, and the tracker share one definition (A/C).\n// C's derived per-session name keeps the historical `dsh-agent-` prefix �?it is\n// a distinct generated pattern, not the named-slot default.\nconst AUTO_SPACE_PREFIX = 'dsh-agent-'\nconst DEFAULT_MAX_OUTPUT_BYTES = 4 * 1024 * 1024\nconst DEFAULT_GRACE_MS = 15_000\nconst TOOL_TIMEOUT_MS = 120_000\n\nexport interface ActiveSpaceTracker {\n  current(): string | number\n  opened(args: { name?: string | number }, result: { id?: string | number; name?: string; done?: boolean; [key: string]: unknown }): void\n  selected(space: string | number): void\n  closed(space: string | number, done: boolean): void\n  /** Drop a stale numeric id back to the remembered space name (or default). */\n  resetToName(): void\n}\n\n/** Build the script that runs the probe and emits a sentinel payload. */\nfunction humanCheckScript(space: string | number): string {\n  return (\n    `${useSpace(space)}${ensureRealTab()}` +\n    `let __hc = null\\n` +\n    `try { __hc = await page.evaluate(${j(HUMAN_CHECK_PROBE)}) } catch { __hc = null }\\n` +\n    `console.log('${SENTINEL}' + JSON.stringify({ ok: true, humanCheck: __hc }))\\n`\n  )\n}\n\n/**\n * Script that blocks until the human clears a challenge.\n *\n * Polls the page (rather than sleeping once) so it returns as soon as the user\n * solves the CAPTCHA or completes the login. When `selector` is given, that\n * element must also exist — the usual \"logged in now\" signal. Returns a\n * structured payload, never an error: `resolved:false` is the honest answer\n * when the deadline passes.\n */\nexport function waitForHumanScript(\n  space: string | number,\n  opts: { timeoutMs: number; pollMs?: number; selector?: string },\n): string {\n  const pollMs = opts.pollMs ?? 2000\n  const selector = opts.selector ?? ''\n  const selectorCheck =\n    selector === ''\n      ? '  const __selOk = true\\n'\n      : `  let __selOk = false\\n  try { __selOk = !!(await page.evaluate(${j(\n          `document.querySelector(${JSON.stringify(selector)}) != null`,\n        )})) } catch { __selOk = false }\\n`\n  return (\n    `${useSpace(space)}${ensureRealTab()}` +\n    `const __wb = Date.now()\\n` +\n    `let __saw = false, __resolved = false, __polls = 0, __last = null\\n` +\n    `for (;;) {\\n` +\n    `  let __hc = null\\n` +\n    `  try { __hc = await page.evaluate(${j(HUMAN_CHECK_PROBE)}) } catch { __hc = null }\\n` +\n    `  if (__hc && __hc.detected) __saw = true\\n` +\n    `  __last = __hc\\n` +\n    selectorCheck +\n    `  if (!(__hc && __hc.detected) && __selOk) { __resolved = true; break }\\n` +\n    `  if (Date.now() - __wb >= ${opts.timeoutMs}) break\\n` +\n    `  __polls++\\n` +\n    `  await page.waitForTimeout(${pollMs})\\n` +\n    `}\\n` +\n    `console.log('${SENTINEL}' + JSON.stringify({ ok: true, needed: __saw, resolved: __resolved, waitedMs: Date.now() - __wb, polls: __polls, detected: !!(__last && __last.detected), kind: (__last && __last.kind) || null, url: await page.url().catch(() => null) }))\\n`\n  )\n}\n\nexport function createActiveSpaceTracker(defaultSpace: string | number = DEFAULT_SPACE): ActiveSpaceTracker {\n  let activeSpace: string | number = defaultSpace\n  let activeName: string | null = typeof defaultSpace === 'string' ? defaultSpace : null\n  return {\n    current: () => activeSpace,\n    opened: (args, result) => {\n      activeName = result?.name ?? str(args?.name, defaultSpace as string) ?? null\n      activeSpace = result?.id ?? activeName ?? defaultSpace\n    },\n    selected: (space) => {\n      if (space !== undefined && space !== '') {\n        activeSpace = space\n        activeName = typeof space === 'string' ? space : null\n      }\n    },\n    closed: (space, done) => {\n      if (done && (String(space) === String(activeSpace) || (activeName !== null && String(space) === String(activeName)))) {\n        activeSpace = defaultSpace\n        activeName = typeof defaultSpace === 'string' ? defaultSpace : null\n      }\n    },\n    // A browser restart resets the runtime's space table, leaving the\n    // remembered NUMERIC id dangling �?the runtime then hard-fails every\n    // tool with \"task space not found: N\" until the user manually reopens a\n    // space. Falling back to the space's NAME lets useOrCreate recreate it.\n    resetToName: () => {\n      activeSpace = activeName ?? defaultSpace\n    },\n  }\n}\n\n/**\n * B �?the session-keyed form of the tracker. Two DSH agents driving the same\n * browser each get their own slot, so \"the most recently opened space\" for one\n * agent never bleeds into the other. The public surface is identical to\n * `createActiveSpaceTracker` (every method routes to the CURRENT session's\n * slot), so `runWithStaleSpaceRetry` / `afterExecute` need no per-call-site\n * change �?only `setCurrentSession` is injected once per execute, inside the\n * already-global `withEgoLock` (which keeps the slot choice race-free).\n *\n * `defaultNameFor(sessionKey)` resolves the fallback slot name for a session �? * this is where C's `:auto` �?`dsh-agent-<sid8>` derivation lives. It is a\n * closure over the live config, so a volatile `defaultSpace` / `isolateSpaces`\n * edit is reflected on the NEXT freshly-created slot.\n */\nexport interface SessionSpaceTracker extends ActiveSpaceTracker {\n  /**\n   * Set the active session for the current tool call. The optional `linkScope`\n   * parameter (P0-1, Tabbit bridge) isolates slot state per link so switching\n   * between ego-cli / tabbit-cli / cdp does not leak space state across backends.\n   * When omitted, behaviour is identical to the pre-1.8.x single-scope model.\n   */\n  setCurrentSession(id: string | undefined, linkScope?: string): void\n  currentSession(): string | undefined\n  /**\n   * The active space of the most-recently-touched REAL (non-global) session,\n   * or null when no session-scoped call has run yet. The ego-cli frame poller\n   * observes this instead of `current()` (which is `default` for the global\n   * slot), so it never registers or screenshots the shared default space.\n   */\n  lastActiveSpace(): string | number | null\n}\n\nexport const GLOBAL_SESSION_KEY = '__global__'\n\n/**\n * C — resolve the fallback slot name for a session.\n *\n * v1.6.0 — SESSION ISOLATION IS THE DEFAULT. `defaultSpace` ships as `:auto`,\n * so a call that omits `space` lands in a per-session task space\n * `dsh-agent-<sid8>` instead of the shared `default` slot. The sentinel is\n * honoured regardless of `isolateSpaces`, because space NAMING and PROFILE\n * persistence are two different axes: `isolateSpaces` only decides whether the\n * browser profile lives on disk or in an in-memory sandbox.\n *\n * A caller that deliberately wants the shared slot sets `defaultSpace` to a\n * named value (e.g. `default`) or passes `space: 'default'` on a call — the\n * tracker then pins that session to it. Calls carrying NO session id always\n * fall back to the named shared slot so pre-existing behaviour keeps working.\n * Any other configured value passes through verbatim.\n * @internal exported for tests\n */\nexport function deriveSlotDefaultName(\n  rc: { defaultSpace: string; isolateSpaces: boolean },\n  sessionKey: string,\n): string {\n  const name = rc.defaultSpace\n  if (name === AUTO_SPACE_SENTINEL) {\n    if (sessionKey === GLOBAL_SESSION_KEY) return DEFAULT_SPACE\n    return AUTO_SPACE_PREFIX + sessionSpaceToken(sessionKey)\n  }\n  return name\n}\n\n/**\n * A stable, space-name-safe 8-char token for a DSH session id.\n *\n * DSH session ids look like `session-52adc205-3251-…`, so the old\n * `slice(0, 8)` yielded the literal `session-` for EVERY session — silently\n * collapsing all sessions into one space, i.e. exactly the failure this\n * feature exists to prevent. The known prefix is stripped and\n * hyphens kept, other non-alphanumerics dropped, then sliced to 8; a short id\n * is used as-is (still unique), and only a degenerate/empty id falls back to a\n * deterministic FNV-1a hash so the name is never empty.\n * @internal exported for tests\n */\nexport function sessionSpaceToken(sessionId: string): string {\n  // Keep hyphens (a space name may contain them, and it stays readable);\n  // drop everything else so the token is always a legal space name.\n  const bare = sessionId.replace(/^session-/, '').replace(/[^A-Za-z0-9-]/g, '')\n  if (bare.length > 0) return bare.slice(0, 8)\n  // An empty/degenerate id still needs a non-empty, deterministic token.\n  let h = 0x811c9dc5\n  for (let i = 0; i < sessionId.length; i += 1) {\n    h ^= sessionId.charCodeAt(i)\n    h = Math.imul(h, 0x01000193) >>> 0\n  }\n  return h.toString(16).padStart(8, '0').slice(0, 8)\n}\n\nexport function createSessionSpaceTracker(\n  defaultNameFor: (sessionKey: string) => string | number = () => DEFAULT_SPACE,\n): SessionSpaceTracker {\n  interface Slot { activeSpace: string | number; activeName: string | null }\n  const slots = new Map<string, Slot>()\n  let sessionKey: string = GLOBAL_SESSION_KEY\n  let session: string | undefined\n  // The most-recently-touched REAL (non-global) session key. The ego-cli frame\n  // poller runs outside any tool execution, so it cannot read the per-call\n  // session slot — without this it fell back to the `__global__` slot and\n  // registered/screenshotted the shared `default` space instead of the agent's\n  // own `dsh-agent-<sid8>` space. This tracks where the agent actually works.\n  let linkScope: string = ''  // P0-1: active link id for cross-backend slot isolation\n  let lastRealKey: string | null = null\n  /**\n   * Compose the full slot key. When linkScope is '' (legacy / single-backend),\n   * the key equals sessionKey so all pre-existing behaviour is preserved.\n   */\n  const composeKey = (): string => linkScope ? `${sessionKey}\\x00${linkScope}` : sessionKey\n  const noteReal = (): void => { if (sessionKey !== GLOBAL_SESSION_KEY) lastRealKey = composeKey() }\n  const slotOf = (key: string): Slot => {\n    let s = slots.get(key)\n    if (!s) {\n      // Strip linkScope from the key before naming, so deriveSlotDefaultName\n      // / sessionSpaceToken always receives the pure session id.\n      const bareSession = key.split('\\x00')[0]!\n      const def = defaultNameFor(bareSession)\n      s = { activeSpace: def, activeName: typeof def === 'string' ? def : null }\n      slots.set(key, s)\n    }\n    return s\n  }\n  // Slots are keyed by session id; the number of concurrent agents is small and\n  // bounded, so retention (no eviction) is intentional �?a WeakMap over string\n  // keys is impossible and a LRU would drop a paused agent's remembered space.\n  const withSlot = (fn: (s: Slot, def: string | number) => void): void => {\n    const s = slotOf(composeKey())\n    fn(s, defaultNameFor(sessionKey))\n  }\n  return {\n    setCurrentSession: (id, newLinkScope) => {\n      session = id\n      sessionKey = id ?? GLOBAL_SESSION_KEY\n      if (newLinkScope !== undefined) linkScope = newLinkScope\n      noteReal()\n    },\n    currentSession: () => session,\n    current: () => slotOf(composeKey()).activeSpace,\n    lastActiveSpace: () => (lastRealKey === null ? null : slotOf(lastRealKey).activeSpace),\n    opened: (args, result) => {\n      noteReal()\n      withSlot((s, def) => {\n        s.activeName = result?.name ?? str(args?.name, def as string) ?? null\n        s.activeSpace = result?.id ?? s.activeName ?? def\n      })\n    },\n    selected: (space) => {\n      if (space !== undefined && space !== '') {\n        noteReal()\n        withSlot((s) => {\n          s.activeSpace = space\n          s.activeName = typeof space === 'string' ? space : null\n        })\n      }\n    },\n    closed: (space, done) => {\n      withSlot((s, def) => {\n        if (done && (String(space) === String(s.activeSpace) || (s.activeName !== null && String(space) === String(s.activeName)))) {\n          s.activeSpace = def\n          s.activeName = typeof def === 'string' ? def : null\n        }\n      })\n    },\n    resetToName: () => {\n      withSlot((s, def) => { s.activeSpace = s.activeName ?? def })\n    },\n  }\n}\n\n// ── serialization ───────────────────────────────────────────────────────────\n/**\n * The bundled runtime host is a single persistent browser shared by every tool\n * call; concurrent tool executions would race on the same task space / tabs. All\n * bcdp_* executions are therefore serialized through ONE queue lane.\n *\n * The lane is shared with the automatic sources (tab inventory, frame capture),\n * which run at `opportunistic` priority: they are dropped while a tool call owns\n * the lane instead of queueing behind it. Before this, the pollers did not take\n * the lock at all — they only LOOKED at it — so a 2.6 s capture and a tool call\n * could hit the same browser concurrently.\n */\nconst BACKEND_LANE = 'backend'\nconst backendQueue = createRunQueue({\n  onEvent: (_key, event) => bumpQueue(event),\n})\n/**\n * How many bcdp_* executions are currently inside the lock body (0 = idle).\n * The CLI frame poller reads this via `egoLockBusy()` to skip a tick while a\n * real tool call owns the browser — a passive observer must never contend with\n * an action. Incremented the moment the queued job starts, decremented when its\n * body settles, so a queued-but-not-yet-run call does not falsely read busy.\n */\nlet egoLockDepth = 0\nexport function egoLockBusy(): boolean {\n  return egoLockDepth > 0\n}\nfunction withEgoLock<T>(fn: () => Promise<T> | T): Promise<T> {\n  return backendQueue.run({\n    key: BACKEND_LANE,\n    run: async () => {\n      egoLockDepth += 1\n      try {\n        return await fn()\n      } finally {\n        egoLockDepth -= 1\n      }\n    },\n  })\n}\n\n// ── environment self-adaptation ──────────────────────────────────────────────\n/**\n * Build the env handed to `ego-browser nodejs` spawns.\n *\n * The vendored ego-linux CLI reads EGO_LINUX_CHROME (bare Chrome binary/wrapper\n * path) and EGO_LINUX_HEADLESS (=1 to run headless) from the process env. When a\n * host does not set them �?the common case on root / Docker / CI boxes �?Chrome\n * silently fails to start, and consumers see a 20s `DevTools port` timeout.\n *\n * This function makes the plugin self-sufficient WITHOUT touching the host or\n * other plugins:\n *\n *  - It is a pure function: only reads the current process env, never mutates\n *    it, never writes files, and returns a fresh env to pass to the one spawn.\n *  - It INCREMENTALLY FILLS GAPS: it uses `??` on every value, so an env var the\n *    user already set is always respected and never overridden (\"user wins\").\n *  - It only compensates for missing pieces, so behavior on a correctly set-up\n *    host is byte-for-byte identical to before.\n *  - It is idempotent: the same env yields the same result every call.\n *  - An opt-out switch EGO_BROWSER_AUTO_ADAPT (set to \"0\"/\"false\"/\"no\") restores\n *    the original \"inherit host env verbatim\" behavior.\n */\n/** 阶段 10 �?the render worker: the ONLY thing that can see a page. */\nconst RENDER_WORKER_BIN = fileURLToPath(new URL('../bin/cdp-render-worker.mjs', import.meta.url))\nconst BUNDLED_WRAPPER = fileURLToPath(\n  new URL('../bin/cdp-chrome-wrapper.sh', import.meta.url),\n)\nconst IS_WIN = process.platform === 'win32'\nconst IS_DARWIN = process.platform === 'darwin'\nconst AUTO_ADAPT_OFF = /^(0|false|no)$/i.test(\n  process.env.EGO_BROWSER_AUTO_ADAPT ?? '',\n)\nconst COMMON_CHROME_BINS = [\n  'google-chrome-stable',\n  'google-chrome',\n  'chromium',\n  'chromium-browser',\n  '/usr/bin/google-chrome-stable',\n  '/usr/bin/google-chrome',\n  '/usr/bin/chromium',\n  '/usr/bin/chromium-browser',\n  '/opt/google/chrome/google-chrome',\n]\n/** Windows registry-free probe of the usual install dirs (no subprocess). */\nfunction windowsChromeCandidates(): string[] {\n  const pf = process.env.ProgramFiles\n  const pfx86 = process.env['ProgramFiles(x86)']\n  const local = process.env.LOCALAPPDATA\n  const base =\n    local ||\n    `${process.env.USERPROFILE || process.env.HOME || ''}\\\\AppData\\\\Local`\n  const b = (p: string | undefined): string | undefined => (p ? p.replace(/\\\\+$/, '') : p)\n  const out = [\n    b(pf) + '\\\\Google\\\\Chrome\\\\Application\\\\chrome.exe',\n    b(pfx86) + '\\\\Google\\\\Chrome\\\\Application\\\\chrome.exe',\n    b(local) + '\\\\Google\\\\Chrome\\\\Application\\\\chrome.exe',\n    b(pf) + '\\\\Microsoft\\\\Edge\\\\Application\\\\msedge.exe',\n    b(pfx86) + '\\\\Microsoft\\\\Edge\\\\Application\\\\msedge.exe',\n    b(local) + '\\\\Microsoft\\\\Edge\\\\Application\\\\msedge.exe',\n    b(pfx86) + '\\\\BraveSoftware\\\\Brave-Browser\\\\Application\\\\brave.exe',\n    b(local) + '\\\\BraveSoftware\\\\Brave-Browser\\\\Application\\\\brave.exe',\n  ]\n  return out.filter(Boolean) as string[]\n}\n/**\n * macOS registry-free probe of the usual `.app` bundles (no subprocess).\n *\n * Chrome on macOS is never on PATH: the launcher lives inside the bundle at\n * `<App>.app/Contents/MacOS/<binary>`. Both the system-wide and per-user\n * `/Applications` locations are probed, Chrome first so that a machine with\n * several browsers picks the same one the README documents.\n */\nfunction darwinChromeCandidates(): string[] {\n  const roots = ['/Applications']\n  if (process.env.HOME) {\n    roots.push(`${process.env.HOME}/Applications`)\n  }\n  const bundles = [\n    'Google Chrome.app/Contents/MacOS/Google Chrome',\n    'Chromium.app/Contents/MacOS/Chromium',\n    'Microsoft Edge.app/Contents/MacOS/Microsoft Edge',\n    'Brave Browser.app/Contents/MacOS/Brave Browser',\n    'Tungsten Edge.app/Contents/MacOS/Tungsten Edge',\n  ]\n  const out: string[] = []\n  for (const root of roots) {\n    for (const bundle of bundles) {\n      out.push(`${root}/${bundle}`)\n    }\n  }\n  return out\n}\n/** Find a usable Chrome binary by scanning PATH + common fixed locations. */\nexport function findChromeBinary(): string | undefined {\n  if (process.env.EGO_LINUX_CHROME) {\n    return process.env.EGO_LINUX_CHROME\n  }\n  // Windows: probe install dirs first, then walk PATH with %PATHEXT%.\n  if (IS_WIN) {\n    for (const p of windowsChromeCandidates()) {\n      try {\n        if (existsSync(p)) {\n          return p\n        }\n      } catch {\n        // fall through\n      }\n    }\n    const exts = (process.env.PATHEXT ?? '.EXE;.CMD;.BAT;.COM')\n      .split(';')\n      .filter(Boolean)\n      .map((e) =>\n        e.startsWith('.') ? e.toLowerCase() : `.${e.toLowerCase()}`,\n      )\n    const dirs = (process.env.PATH ?? '')\n      .split(';')\n      .map((d) => d.replace(/^\"|\"$/g, ''))\n      .filter(Boolean)\n    for (const dir of dirs) {\n      for (const name of ['chrome', 'msedge', 'brave']) {\n        for (const ext of exts) {\n          try {\n            const p = `${dir}\\\\${name}${ext}`\n            if (existsSync(p)) {\n              return p\n            }\n          } catch {\n            // fall through\n          }\n        }\n      }\n    }\n    return undefined\n  }\n  // macOS: Chrome lives inside a `.app` bundle, never on PATH. Probe the bundle\n  // locations and stop there — the POSIX PATH walk below cannot find it (there\n  // is no `google-chrome` shim on macOS), so falling through only wastes time.\n  if (IS_DARWIN) {\n    for (const p of darwinChromeCandidates()) {\n      try {\n        if (existsSync(p)) {\n          return p\n        }\n      } catch {\n        // fall through\n      }\n    }\n    return undefined\n  }\n  // POSIX: absolute + PATH walk.\n  for (const name of COMMON_CHROME_BINS) {\n    if (name.includes('/')) {\n      try {\n        if (existsSync(name)) {\n          return name\n        }\n      } catch {\n        // fall through\n      }\n    } else {\n      for (const dir of (process.env.PATH ?? '').split(':')) {\n        if (!dir) {\n          continue\n        }\n        const p = `${dir}/${name}`\n        try {\n          if (existsSync(p)) {\n            return p\n          }\n        } catch {\n          // fall through\n        }\n      }\n    }\n  }\n  return undefined\n}\n/** Root detection only makes sense on POSIX; Windows doesn't gate on sandbox. */\nfunction isPosixRoot(platform: NodeJS.Platform = process.platform): boolean {\n  const uid = process.getuid?.()\n  return typeof uid === 'number' && uid === 0 && platform !== 'win32'\n}\n/** No display server �?headless is required (Linux/macOS headless servers). */\nfunction isHeadlessDetected(platform: NodeJS.Platform = process.platform, env: NodeJS.ProcessEnv = process.env): boolean {\n  // Windows and macOS always have a desktop session; only Linux headless servers need to run the backing browser headless.\n  if (platform === 'win32' || platform === 'darwin') {\n    return false\n  }\n  return env.DISPLAY === undefined || env.DISPLAY === ''\n}\n/**\n * Build the env handed to `ego-browser nodejs` spawns. See the block comment\n * above (\"environment self-adaptation\") for the design contract.\n *\n * Platform/env are injectable for testing; production calls use process defaults.\n */\nexport function resolveEgoEnv(cfg: Partial<ResolvedConfig>, { platform = process.platform, baseEnv = process.env }: { platform?: NodeJS.Platform; baseEnv?: NodeJS.ProcessEnv } = {}): NodeJS.ProcessEnv {\n  if (AUTO_ADAPT_OFF) {\n    // New switch explicitly disabled: original behavior, inherit verbatim.\n    return baseEnv\n  }\n  const env: NodeJS.ProcessEnv = { ...baseEnv }\n  // Electron hosts (DSH Desktop): process.execPath is the Electron binary, and\n  // every spawn below passes this explicit env �?without ELECTRON_RUN_AS_NODE=1\n  // the child boots as a second Electron app instead of running the script\n  // (empty stderr, no @@DSH_RESULT@@ sentinel; issue #42). User-set value wins.\n  if ((process.versions as { electron?: string }).electron && env.ELECTRON_RUN_AS_NODE === undefined) {\n    env.ELECTRON_RUN_AS_NODE = '1'\n  }\n  const chrome = findChromeBinary()\n  // Settings-configured chrome path (highest priority after user-set env).\n  // An empty string means \"auto-detect\" �?skip so the platform branches below\n  // can run.\n  const configChrome = cfg?.chromePath\n  if (env.EGO_LINUX_CHROME === undefined && configChrome) {\n    env.EGO_LINUX_CHROME = configChrome\n  }\n  // Root / Docker / CI: Chrome refuses to run without --no-sandbox. The\n  // wrapper execs the real binary with --no-sandbox (EGO_LINUX_CHROME takes a\n  // bare path, so a wrapper is required). Never override a user-set value.\n  if (env.EGO_LINUX_CHROME === undefined && isPosixRoot(platform) && chrome) {\n    env.EGO_LINUX_CHROME = BUNDLED_WRAPPER\n  }\n  // Windows: no --no-sandbox needed (Windows Chrome has no sandbox gate), and\n  // the bundled wrapper is a POSIX shell script that cannot run here. Pass the\n  // binary path directly so the vendored runtime (which uses POSIX `which`)\n  // doesn't have to resolve it itself.\n  //\n  // macOS shares both properties: no sandbox gate (the wrapper exists only to\n  // add --no-sandbox for root/Docker on Linux), and the vendored runtime's\n  // name-based lookup would never find a path inside a `.app` bundle. Without\n  // this branch EGO_LINUX_CHROME is never injected on darwin and the first\n  // cold start fails with \"no Chrome/Chromium binary found\" (issue #68).\n  if (env.EGO_LINUX_CHROME === undefined && (platform === 'win32' || platform === 'darwin') && chrome) {\n    env.EGO_LINUX_CHROME = chrome\n  }\n  // Headless servers (no DISPLAY) must run the backing browser headless.\n  if (env.EGO_LINUX_HEADLESS === undefined && isHeadlessDetected(platform, env)) {\n    env.EGO_LINUX_HEADLESS = '1'\n  }\n  // User-configured extra Chrome args (settings field `chromeArgs`). Bridge to\n  // EGO_LINUX_EXTRA_ARGS, which the vendored runtime's launch() spreads into\n  // the Chrome argv. A user-set env var wins (escape hatch for power users).\n  // The value is the RAW string; the runtime tokenizes + filters it so the\n  // same blocklist applies on both sides of the boundary.\n  const configChromeArgs = cfg?.chromeArgs\n  if (env.EGO_LINUX_EXTRA_ARGS === undefined && typeof configChromeArgs === 'string' && configChromeArgs.trim() !== '') {\n    env.EGO_LINUX_EXTRA_ARGS = configChromeArgs\n  }\n  if (env.EGO_ISOLATE_SPACES === undefined && cfg?.isolateSpaces !== undefined) {\n    env.EGO_ISOLATE_SPACES = cfg.isolateSpaces ? '1' : '0'\n  }\n  // ── R1: point the runtime at the ACTIVATED CDP target ───────────────────\n  // `resolveEgoEnv` stays synchronous (every spawn site calls it inline), so\n  // it reads the attach cache that the host refreshes whenever settings\n  // change �?see the `triggerCdpRefresh` wiring in apply(). The cache, not\n  // this function, owns the probe; this function only applies the decision.\n  const decision = decideCdpAttach(cfg)\n  if (decision.kind === 'inject') env[EGO_LINUX_CDP_URL] = decision.wsUrl\n  // ── R4: cursor HUD material (drawn into screenshots by the runtime) ─────\n  if (env.EGO_LINUX_CURSOR === undefined && cfg?.cursorHud !== undefined) {\n    env.EGO_LINUX_CURSOR = cfg.cursorHud ? '1' : '0'\n  }\n  if (env.EGO_LINUX_CURSOR_NAME === undefined && typeof cfg?.cursorName === 'string' && cfg.cursorName !== '') {\n    env.EGO_LINUX_CURSOR_NAME = cfg.cursorName\n  }\n  return env\n}\n\n/**\n * The channel that owns routing right now: `resolveEffectiveLink` over the\n * CURRENT config (activation first, sequence order as the visible fallback),\n * plus the attach cache SCOPED to that link. After any links event\n * (enable/activation toggle, reorder, add, remove) the async refresh may still\n * be probing; a cache row describing the PREVIOUS owner must not leak its\n * linkKind/cliPath/wsUrl into the new channel's spawn decisions.\n */\nexport function effectiveChannel(cfg: Partial<ResolvedConfig>): { effective: EffectiveLink | null; attach: AttachState } {\n  const effective = resolveEffectiveLink(cfg.links ?? [], cfg.activeTargetId ?? '')\n  const live = defaultAttachCache.get()\n  const attach = effective && attachMatchesLink(live, effective.link) ? live : emptyAttachState()\n  return { effective, attach }\n}\n\n/**\n * Read the attach decision for the CURRENTLY configured mode/activation.\n * Pure over (cfg, cache) — the decision table itself lives in cdp-targets.ts.\n */\nexport function decideCdpAttach(cfg: Partial<ResolvedConfig>): AttachDecision {\n  const { effective, attach } = effectiveChannel(cfg)\n  return decideAttach({\n    mode: cfg?.cdpMode ?? 'auto',\n    hasActive: effective !== null,\n    status: attach.status,\n    wsUrl: attach.wsUrl,\n    code: attach.code,\n    message: attach.message,\n    allowLocalFallback: Boolean(cfg?.allowLocalFallback),\n    // Config is the source of truth for the remote switch — the cache copy can\n    // lag one refresh behind a toggle.\n    remoteDisabled: cfg?.remoteEnabled === false,\n    // The decision table reads runtime FACTS (does this channel own its\n    // browser? does it hand over an endpoint to inject?), never a kind: the\n    // effective channel decides, and a stale cache row from a previous owner\n    // must not.\n    ...(effective\n      ? {\n          ownsBrowser: runtimeOfLink(effective.link)?.ownsUserBrowser === true,\n          injectsEndpoint: runtimeOfLink(effective.link)?.injectsEndpoint === true,\n        }\n      : {}),\n    // M0.9 launcher (stage 2b) is wired: an authorized fallback launches a\n    // managed local browser inside refreshAttach (async path), so the sync\n    // decision table just needs to know the capability exists.\n    localLauncherReady: true,\n  })\n}\n\n/**\n * Gating helper for every browser-driving spawn. Returns a human-readable\n * reason when the call must NOT reach the runtime, or null when it may\n * proceed. `local` decisions always pass: that is the explicit escape hatch\n * the user asked for.\n */\nexport function cdpAttachError(cfg: Partial<ResolvedConfig>): string | null {\n  const decision = decideCdpAttach(cfg)\n  if (decision.kind === 'error') return `${decision.code}: ${decision.message}`\n  return null\n}\nfunction describeStderr(stderr: string): string {\n  const tail = stderr.trim()\n  return tail === ''\n    ? ''\n    : `\\n--- ego-browser stderr (tail) ---\\n${tail.slice(-2000)}`\n}\nfunction describeSpawnFailure(err: unknown): string {\n  const msg = err instanceof Error ? err.message : String(err)\n  if (\n    /ENOENT|spawn .* ENOENT|not found|could not load|cannot find module/i.test(\n      msg,\n    )\n  ) {\n    return (\n      'ego-browser CLI could not be started. For the vendored runtime, make sure a Chrome/Chromium is reachable (PATH, or set EGO_LINUX_CHROME; root users need a --no-sandbox wrapper, see AGENTS.md). To use an official host instead, set egoBin to your `ego-browser` command. ' +\n      msg\n    )\n  }\n  return `failed to start ego-browser: ${msg}`\n}\n/**\n * Error signatures that indicate a TRANSIENT browser cold-start / channel\n * not-yet-ready problem rather than a real defect. The bundled runtime host is a\n * single persistent Chromium that cold-starts on the first tool call of a\n * session; a probe that arrives while the DevTools/CDP channel is still\n * coming up can fail with one of these. Such failures are safe to retry\n * briefly (the browser keeps warming up in the background). Anything else\n * must pass through immediately �?never mask a genuine error.\n */\nconst COLD_START_SIGNS = [\n  /CDP channel is not open/i,\n  /DevTools.*(port|timeout|active)/i,\n  /could not connect to/i,\n  /browser (was |is )?not (reachable|running|ready)/i,\n  /target.*(closed|not found|detached|crashed)/i,\n  /ECONNREFUSED/i,\n]\nfunction isColdStartError(message: string): boolean {\n  return COLD_START_SIGNS.some((re) => re.test(message))\n}\ninterface WarmupResult {\n  ok: boolean\n  error?: string\n  value?: unknown\n  stdout: string\n  stderr: string\n}\n/**\n * Run `fn` (a per-call `ego-browser` spawn) up to `tries` times with a short\n * backoff, retrying ONLY when the failure matches a transient cold-start\n * signature. Real errors return on their first occurrence so they are never\n * masked. Each retry re-spawns a fresh process, which is exactly what lets a\n * warmed-up browser connect on a later attempt.\n */\nasync function withWarmupRetry(fn: () => Promise<WarmupResult>, { tries = 3, baseDelayMs = 600 }: { tries?: number; baseDelayMs?: number } = {}): Promise<WarmupResult> {\n  let last: WarmupResult | undefined\n  for (let i = 0; i < tries; i++) {\n    const result = await fn()\n    if (result.ok || !isColdStartError(result.error ?? '')) {\n      return result\n    }\n    last = result\n    if (i < tries - 1) {\n      await new Promise((resolve) =>\n        setTimeout(resolve, baseDelayMs * (i + 1)),\n      )\n    }\n  }\n  return last!\n}\n/**\n * Run an ego script, recovering once from a stale space pointer: a browser\n * restart wipes the runtime's space table, so the tracker's remembered numeric\n * id dangles and the runtime hard-fails with \"task space not found: N\".\n * Reset the tracker to the space's name (useOrCreate recreates it) and retry.\n */\n/**\n * Idle reaper decision (issue #47), pure for tests. Reaps only when the\n * feature is on AND at least one bcdp_* call has ever happened (a never-used\n * browser is not running anyway).\n * @internal exported for tests\n */\nexport function shouldReapBrowser(nowMs: number, lastActivityMs: number, idleTimeoutMin: number): boolean {\n  if (!(idleTimeoutMin > 0) || !(lastActivityMs > 0)) return false\n  return nowMs - lastActivityMs > idleTimeoutMin * 60_000\n}\n\n/**\n * Pop the agent browser out as a REAL visible window (issue #51). The\n * runtime's `--open` subcommand replaces a headless instance with a headed\n * one on the same profile (tabs restore) or just raises the existing window.\n * `--open` is on the runtimeArgs blocklist only because USER-supplied args\n * must not steal the window �?here it is an explicit user action from the\n * watch panel. --open stops+relaunches when headless, so give it real time.\n */\nasync function openAgentWindow(ctx: EgoContext, cfg: EgoRuntimeConfig): Promise<{ ok: boolean; error?: string }> {\n  try {\n    const gate = cdpAttachError(cfg)\n    if (gate) return { ok: false, error: gate }\n    // R4/F11 �?an `ego-cli` link drives the ego lite window the user already\n    // has open and can see. There is no headless instance to pop out, and the\n    // native CLI does not implement `--open`. Succeed explicitly (with a log)\n    // instead of spawning a command that would fail.\n    if (effectiveChannel(cfg).effective?.link.kind === EGO_CLI_KIND) {\n      ctx.logger?.info?.('dsh-browser-cdp: ego-cli: browser already visible, skipping --open')\n      return { ok: true }\n    }\n    const handle = ctx.subprocess.spawn({\n      argv: [...cfg.egoArgvPrefix, '--open'],\n      cwd: process.cwd(),\n      env: resolveEgoEnv(cfg),\n      stdio: {\n        stdin: { data: '' },\n        stdout: { maxBytes: 4096 },\n        stderr: { maxBytes: 4096 },\n      },\n      graceMs: 25_000,\n    })\n    const outcome = await handle.done\n    if (outcome.exitCode !== 0) {\n      const stderr = readAll(handle.collected.stderr).trim()\n      return { ok: false, error: stderr || `ego-browser --open exited with code ${outcome.exitCode}` }\n    }\n    return { ok: true }\n  } catch (err) {\n    return { ok: false, error: describeSpawnFailure(err) }\n  }\n}\n\n/** @internal exported for tests */\nexport async function runWithStaleSpaceRetry(  ctx: EgoContext,\n  cfg: EgoRuntimeConfig,\n  exec: ExecLike,\n  buildScript: () => string,\n  graceOverrideMs?: number,\n): Promise<WarmupResult> {\n  let result = await withWarmupRetry(() => runEgoScript(ctx.subprocess, buildScript(), exec, cfg, graceOverrideMs))\n  if (!result.ok && /task space not found: \\d+/.test(result.error ?? '')) {\n    cfg.spaceTracker.resetToName()\n    result = await withWarmupRetry(() => runEgoScript(ctx.subprocess, buildScript(), exec, cfg, graceOverrideMs))\n  }\n  // A relaunched browser keeps the endpoint but mints a new browser id, so the\n  // cached ws dead-ends. Re-probe the same links once and retry before failing.\n  if (!result.ok && CDP_CONNECT_FAIL_RE.test(result.error ?? '')) {\n    const refreshed = await cfg.refreshAttach?.()\n    if (refreshed === true) {\n      result = await withWarmupRetry(() => runEgoScript(ctx.subprocess, buildScript(), exec, cfg, graceOverrideMs))\n    }\n  }\n  // Degraded ego-cli frame source self-heal: on a fresh Desktop start the mount\n  // probe runs with cliProbeColdStart=false, so it does NOT launch the browser\n  // and attach stays not-ready → the 3s CLI frame poller never starts. A real\n  // tool call DOES launch the browser, but the success path never re-probes, so\n  // the panel stays blank until a settings change. Nudge one re-probe here (the\n  // same entry point that starts the poller), cooled down and only while the\n  // poller is still off and no screencast ws owns the panel.\n  if (result.ok) maybeKickCliPoller(cfg)\n  return result\n}\n\n/** Last time we nudged a re-probe to start the degraded CLI frame poller. */\nlet lastCliPollerKick = 0\n/**\n * Start the ego-cli 3s frame poller after a successful tool call when it failed\n * to start at mount (browser cold-started by the tool, not by the probe).\n * No-op for the screencast route (a resolved CDP ws serves frames itself) and\n * while the poller is already running. Coalesced to at most once per 5s so a\n * burst of tool calls cannot re-probe repeatedly.\n */\nfunction maybeKickCliPoller(cfg: EgoRuntimeConfig): void {\n  if (getAttachEndpoint() !== null) return\n  if (getCliPollStatus().running) return\n  const now = Date.now()\n  if (now - lastCliPollerKick < 5000) return\n  lastCliPollerKick = now\n  // Fire-and-forget: triggerCdpRefresh() re-evaluates cliFrameActive and starts\n  // the poller itself; the tool result must not wait on the probe.\n  void cfg.refreshAttach?.()\n}\n\n/**\n * F — navigate self-heal. A page whose renderer/main thread is wedged makes\n * `page.goto`/`page.reload` hang until the subprocess times out, and the SAME\n * stuck target is re-selected on the next call, so a plain retry never helps.\n * This revives the tab FIRST (open a fresh blank target, then close the wedged\n * active one — order matters: closing last would trip the last-tab guard and\n * leave the dead tab in place), then retries buildScript exactly once.\n *\n * Hard cap is one revive: a second hung attempt is returned verbatim rather\n * than looping, so a genuine error is never masked by tab churn.\n * @internal exported for tests\n */\nexport const TAB_STUCK_RE = /no active tab|navigation (?:timed out|timeout)|page\\.goto[\\s\\S]*timeout|timed out after \\d+ms|net::ERR_|waiting for (?:document|load) timed out|TimeoutError|target closed/i\n\n/**\n * A dead cached ws (the browser was relaunched behind the SAME endpoint) surfaces\n * as this one runtime message — see `runtime/ego-linux/src/transport.mjs`. It is\n * deliberately NOT folded into `TAB_STUCK_RE`: the fix is a re-probe of the link,\n * not a tab swap, so the two recoveries must stay distinguishable.\n */\nexport const CDP_CONNECT_FAIL_RE = /failed to connect to CDP endpoint/i\n\n/** True when a failed run looks like a wedged/absent tab rather than a cold start. */\nexport function isTabStuckFailure(result: WarmupResult): boolean {\n  const hay = `${result.error ?? ''}\\n${result.stderr ?? ''}`\n  return TAB_STUCK_RE.test(hay)\n}\n\n/** Heredoc that swaps the stuck target for a fresh blank one (see runWithTabRevive). */\nfunction tabReviveScript(): string {\n  return (\n    `const __before = await browser.listTabs()\\n` +\n    `const __stuck = __before.find(t => t.active) ?? __before[0]\\n` +\n    `await browser.openOrReuseTab('about:blank', { wait: true, timeout: 8000 })\\n` +\n    `if (__stuck) { await browser.closeTab(__stuck.targetId) }\\n` +\n    `console.log('${SENTINEL}' + JSON.stringify({ ok: true, revived: true, closed: __stuck?.targetId ?? null }))\\n`\n  )\n}\n\n/**\n * @internal exported for tests. Returns the final WarmupResult plus what it\n * recovered from (null on the normal path, so the tool result always carries\n * a `recoveredFrom` field the model can see).\n */\nexport async function runWithTabRevive(\n  ctx: EgoContext,\n  cfg: EgoRuntimeConfig,\n  exec: ExecLike,\n  buildScript: () => string,\n  graceOverrideMs?: number,\n): Promise<{ result: WarmupResult; recoveredFrom: string | null }> {\n  const first = await runWithStaleSpaceRetry(ctx, cfg, exec, buildScript, graceOverrideMs)\n  if (first.ok || !isTabStuckFailure(first)) return { result: first, recoveredFrom: null }\n  const recoveredFrom = (first.error ?? first.stderr ?? 'tab stuck').trim().slice(0, 500)\n  await runEgoScript(ctx.subprocess, tabReviveScript(), exec, cfg, graceOverrideMs)\n  const retried = await runWithStaleSpaceRetry(ctx, cfg, exec, buildScript, graceOverrideMs)\n  return { result: retried, recoveredFrom }\n}\n/**\n * Find the last line carrying the sentinel and JSON-parse its payload.\n *\n * Fallback: `bcdp_script` (with verbatim:true) runs user-authored heredocs, which\n * tool descriptions tell the model to \"end with console.log(JSON.stringify(...))\"\n * �?without the sentinel prefix. A script written to that instruction used to\n * succeed and still be reported as a failure (\"no @@DSH_RESULT@@ payload\"), so\n * when no sentinel line exists we accept the last line that parses as a JSON\n * object. The sentinel still wins whenever it is present (it marks the payload\n * deliberately, across any amount of surrounding log noise).\n *\n * @internal exported for tests\n */\nexport function parseSentinel(stdout: string): Record<string, unknown> | undefined {\n  const lines = stdout.split('\\n')\n  for (let i = lines.length - 1; i >= 0; i--) {\n    const idx = lines[i]!.indexOf(SENTINEL)\n    if (idx === -1) continue\n    const payload = lines[i]!.slice(idx + SENTINEL.length).trim()\n    try {\n      return JSON.parse(payload) as Record<string, unknown>\n    } catch {\n      return undefined\n    }\n  }\n  // Sentinel absent (or its line was malformed): accept a bare JSON object.\n  // Depth-scanned rather than line-scanned, because console.log(JSON.stringify(x,\n  // null, 2)) �?the most natural thing to write �?spans many lines, and the\n  // earlier line-based fallback silently missed it.\n  return lastJsonObject(stdout)\n}\n\n/**\n * The last balanced `{...}` run in `text` that parses as a JSON object.\n *\n * Tracks double-quoted strings (JSON's only string syntax) so braces inside a\n * string value do not unbalance the scan. Invalid candidates are skipped, not\n * fatal: log noise before the payload is common.\n *\n * A candidate must begin its own line (leading whitespace is fine). That keeps\n * pretty-printed payloads working while refusing an object merely mentioned in\n * prose: `[warn] retrying {\"attempt\":2}` must not become the result, because a\n * silently wrong payload is worse than no payload at all.\n */\nfunction lastJsonObject(text: string): Record<string, unknown> | undefined {\n  let best: Record<string, unknown> | undefined\n  let depth = 0\n  let start = -1\n  let inString = false\n  let escaped = false\n  for (let i = 0; i < text.length; i++) {\n    const c = text[i]!\n    if (inString) {\n      if (escaped) escaped = false\n      else if (c === '\\\\') escaped = true\n      else if (c === '\"') inString = false\n      continue\n    }\n    if (c === '\"') { inString = true; continue }\n    if (c === '{') {\n      if (depth === 0) start = i\n      depth += 1\n      continue\n    }\n    if (c !== '}') continue\n    if (depth === 0) continue\n    depth -= 1\n    if (depth !== 0 || start < 0) continue\n    // Only whitespace may sit between the line start and the opening brace.\n    let p = start - 1\n    while (p >= 0 && (text[p] === ' ' || text[p] === '\\t' || text[p] === '\\r')) p -= 1\n    const atLineStart = p < 0 || text[p] === '\\n'\n    try {\n      const parsed = atLineStart ? (JSON.parse(text.slice(start, i + 1)) as unknown) : null\n      if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {\n        best = parsed as Record<string, unknown>\n      }\n    } catch {\n      /* not a JSON object literal; keep the previous best */\n    }\n    start = -1\n  }\n  return best\n}\n\n/** R2/R3 �?sentinel + payload for the `bcdp_status` facade probe. @internal exported for tests */\nexport const STATUS_FACADE_SENTINEL = '__BCDP_STATUS__'\n/** @internal exported for tests �?the exact heredoc the status probe runs. */\nexport const STATUS_FACADE_SCRIPT =\n  `console.log(${JSON.stringify(STATUS_FACADE_SENTINEL)} + JSON.stringify({ ` +\n  'taskSpaces: typeof taskSpaces, browser: typeof browser, page: typeof page }))\\n'\n\nexport interface StatusFacades {\n  taskSpaces: string\n  browser: string\n  page: string\n}\n\n/**\n * Parse the facade payload the status probe prints; `undefined` if absent.\n * @internal exported for tests\n */\nexport function parseStatusFacades(stdout: string): StatusFacades | undefined {\n  const lines = stdout.split('\\n')\n  for (let i = lines.length - 1; i >= 0; i--) {\n    const idx = lines[i]!.indexOf(STATUS_FACADE_SENTINEL)\n    if (idx === -1) continue\n    const payload = lines[i]!.slice(idx + STATUS_FACADE_SENTINEL.length).trim()\n    try {\n      const parsed = JSON.parse(payload) as Partial<StatusFacades>\n      return {\n        taskSpaces: typeof parsed.taskSpaces === 'string' ? parsed.taskSpaces : 'undefined',\n        browser: typeof parsed.browser === 'string' ? parsed.browser : 'undefined',\n        page: typeof parsed.page === 'string' ? parsed.page : 'undefined',\n      }\n    } catch {\n      return undefined\n    }\n  }\n  return undefined\n}\n\n/**\n * R7 �?is the old dsh-ego-browser plugin installed anywhere under this DSH home?\n *\n * Reported (never enforced): the two plugins can coexist now that tool names\n * and routes no longer overlap, but both driving ONE local ego browser would\n * fight over the same task spaces, and that plugin's handoff API has no\n * ownership check. A warning is the honest limit of what we can do here.\n */\nexport function findUpstreamPluginInstall(\n  home: string = process.env.HOME || process.env.USERPROFILE || homedir(),\n): string {\n  const profiles = `${home}/.dsh/profiles`\n  try {\n    for (const profile of readdirSync(profiles)) {\n      const dir = `${profiles}/${profile}/node_modules/dsh-ego-browser`\n      if (existsSync(dir)) return dir\n    }\n  } catch {\n    /* no profiles directory: nothing to report */\n  }\n  return ''\n}\n\n/** The live runtime config object built in apply() (getters read the settings bridge). */\ninterface EgoRuntimeConfig {\n  /** Re-probe the active CDP link; true when it produced a NEW endpoint. */\n  refreshAttach?: () => Promise<boolean>\n  egoBin: string\n  configuredDefaultSpace: string | number\n  spaceTracker: SessionSpaceTracker\n  readonly activeSpace: string | number\n  // A/C — mirrors ResolvedConfig.defaultSpace so EgoRuntimeConfig keeps\n  // satisfying initCastServer(cfg: ResolvedConfig) (see the structural-mirror\n  // note by the judge fields). The live per-session value is `activeSpace`.\n  readonly defaultSpace: string\n  maxOutputBytes: number\n  graceMs: number\n  readonly chromePath: string\n  readonly captureBackend: ResolvedConfig['captureBackend']\n  readonly streamProfile: ResolvedConfig['streamProfile']\n  readonly cdpFps: number\n  readonly cdpQuality: number\n  readonly cdpMaxWidth: number\n  readonly cdpBackstopIntervalMs: number\n  /** Watch-panel tab tracking: 'active' (default) or 'all' (全模式). */\n  readonly tabTracking: 'active' | 'all'\n  readonly viewportWidth: number\n  readonly viewportHeight: number\n  readonly deviceScaleFactor: number\n  readonly ffmpegFps: number\n  readonly ffmpegMaxWidth: number\n  readonly ffmpegBitrateKbps: number\n  readonly ffmpegEncoder: ResolvedConfig['ffmpegEncoder']\n  readonly ffmpegPath: string\n  readonly githubMirror: string\n  readonly runtimeArgs: string\n  readonly idleTimeoutMin: number\n  readonly chromeArgs: string\n  readonly isolateSpaces: boolean\n  // ── 工具分级注入（src/toolTiers.ts）───────────────────────────────\n  readonly toolInjection: ResolvedConfig['toolInjection']\n  readonly toolBrowse: boolean\n  readonly toolExtended: boolean\n  readonly toolEscape: boolean\n  readonly toolJudge: boolean\n  readonly sessionScopedPulse: boolean\n  // ── R1/R7: connection sequence + activation ─────────────────────────────\n  readonly links: BrowserLink[]\n  /** R7 �?extra `ego-cli` rows that sanitize dropped (local-only singleton). */\n  readonly droppedEgoCli: number\n  /**\n   * R7 �?shape-aware argv prefix for the ego CLI. `[node, <file>]` for the\n   * bundled port / `ego-browser-v2`, `[<file>]` for a real executable (the\n   * macOS app-bundle helper). Computed from the attach cache, which knows the\n   * probed shape.\n   */\n  readonly egoArgvPrefix: string[]\n  readonly activeTargetId: string\n  readonly cdpMode: CdpMode\n  readonly cdpProbeTimeoutMs: number\n  // ── R4: screenshot material toggles ─────────────────────────────────────\n  readonly cursorHud: boolean\n  readonly cursorName: string\n  // ── M0.9 local launcher (optional) ──────────────────────────────────────\n  readonly allowLocalFallback: boolean\n  readonly legacyEgoToolNames: boolean\n  readonly localHeadless: boolean\n  readonly remoteEnabled: boolean\n  readonly localUserDataDir: string\n  /** 探测冷启动闸门（默认关）：关 = ego-cli 探测绝不拉起背后的浏览器。 */\n  readonly allowProbeColdStart: boolean\n  /** ego-cli 观察窗降级帧源开关（默认开）：关 = 不轮询截图，观察窗显示占位。 */\n  readonly cliFramePollEnabled: boolean\n  /** Lightpanda backend �?extra `lightpanda serve` args for managed `lightpanda` rows. */\n  readonly lightpandaArgs: string\n  // ── 阶段 10: JEV/Laya judge (design-jev-pipeline.md) ────────────────────\n  //\n  // Listed field-by-field rather than as one `JudgeSettings` object, for a\n  // STRUCTURAL reason and not a stylistic one: `EgoRuntimeConfig` hand-mirrors\n  // `ResolvedConfig`, and several consumers (`initCastServer`) still take a\n  // `ResolvedConfig`. Adding fields here in any other shape makes this type stop\n  // satisfying that one. The duplication is the pre-existing design; this stage\n  // follows it rather than quietly changing the contract under another module.\n  readonly jevUrl: string\n  readonly jevKey: string\n  readonly jevModel: string\n  readonly layaUrl: string\n  readonly layaKey: string\n  readonly layaModel: string\n  readonly judgePrefer: string\n  readonly jevChunkSize: number\n  readonly jevMaxImageBytes: number\n  readonly jevHistoryLimit: number\n  readonly jevArchiveImage: boolean\n  readonly jevEvaluate: boolean\n  readonly jevStepBudget: number\n  readonly jevWallMs: number\n}\n\ninterface ExecLike {\n  signal?: AbortSignal\n}\n\n/** 常驻级工具看到的工具分级视图（活动脉�?+ 活动�?+ 当前注入面）�?*/\ninterface TierView {\n  pulse: (sessionId?: string) => void\n  active: () => boolean\n  surface: () => { live: string[]; sealed: string[] }\n}\n\n/**\n * R1 �?argv for one tool run. Single source of truth for the `--sdk-path`\n * injection: `bcdp_status` and `runEgoScript` must probe/run under the exact\n * same conditions, otherwise \"available\" and \"actually works\" diverge again.\n * @internal exported for tests\n */\nexport function buildEgoToolArgv(\n  prefix: readonly string[],\n  attach: { linkKind?: string; sdkPath?: string },\n  runtimeArgs: string,\n): string[] {\n  const extraCliArgs = filterArgs(runtimeArgs, EGO_CLI_BLOCKED)\n  // Only the ego-cli runtime ever writes a non-empty sdkPath (and only when its\n  // probe proved the flag works — see the R-1 guard). The empty check is the\n  // whole rule, so this no longer re-derives the channel kind here.\n  const sdkArgs =\n    (attach.sdkPath ?? '') !== ''\n      ? ['--sdk-path', attach.sdkPath as string]\n      : []\n  return [...prefix, 'nodejs', ...sdkArgs, ...extraCliArgs]\n}\n\nasync function runEgoScript(subprocess: SubprocessService, script: string, exec: ExecLike, cfg: EgoRuntimeConfig, graceOverrideMs?: number): Promise<WarmupResult> {\n  // HARD GUARD: if tabbit-cli is the active link, never spawn ego runtime.\n  // This prevents Chrome launch via any code path (worker, probe, frame poller).\n  const eff = resolveEffectiveLink(cfg.links, cfg.activeTargetId)\n  // Capability: a channel that does NOT drive the ego runtime must never cause\n  // one to be spawned (its browser belongs to someone else).\n  if (runtimeOfLink(eff?.link)?.channel.egoRuntime === false) {\n    return { ok: false, error: 'the activated CLI channel does not use the ego runtime (no Chrome fallback)', stdout: '', stderr: '' }\n  }\n  let handle\n  try {\n    // R1 �?an `ego-cli` link that opted into `useSdkPath` must get the same\n    // `--sdk-path` injection the probe used. Without it the native CLI has no\n    // `taskSpaces`/`browser`/`page` facade and every script dies on line 1.\n    const { attach } = effectiveChannel(cfg)\n    handle = subprocess.spawn({\n      // Run through the node interpreter so the vendored CLI needs no +x bit.\n      argv: buildEgoToolArgv(cfg.egoArgvPrefix, attach, cfg.runtimeArgs ?? ''),\n      cwd: process.cwd(),\n      env: resolveEgoEnv(cfg),\n      stdio: {\n        stdin: { data: script },\n        stdout: {\n          maxBytes: cfg.maxOutputBytes,\n          spill: { maxBytes: cfg.maxOutputBytes },\n        },\n        stderr: {\n          maxBytes: cfg.maxOutputBytes,\n          spill: { maxBytes: cfg.maxOutputBytes },\n        },\n      },\n      graceMs: Number.isFinite(graceOverrideMs) && graceOverrideMs! > 0\n        ? graceOverrideMs!\n        : cfg.graceMs,\n      ...(exec.signal !== undefined ? { signal: exec.signal } : {}),\n    })\n  } catch (err) {\n    return {\n      ok: false,\n      error: describeSpawnFailure(err),\n      stdout: '',\n      stderr: '',\n    }\n  }\n  let outcome\n  try {\n    outcome = await handle.done\n  } catch (err) {\n    return {\n      ok: false,\n      error: describeSpawnFailure(err),\n      stdout: '',\n      stderr: '',\n    }\n  }\n  const stdout = readAll(handle.collected.stdout)\n  const stderr = readAll(handle.collected.stderr)\n  if (exec.signal !== undefined && exec.signal.aborted) {\n    return {\n      ok: false,\n      error: 'ego-browser tool aborted (harness timeout or cancellation)',\n      stdout,\n      stderr,\n    }\n  }\n  if (outcome.exitCode !== 0) {\n    // When run through the node interpreter, a missing CLI surfaces as a\n    // module-load failure with exit 1 instead of a spawn error �?normalize it\n    // to the same clear \"CLI not available\" message.\n    const missingModule = /Cannot find module|MODULE_NOT_FOUND/i.test(stderr)\n    return {\n      ok: false,\n      error: missingModule\n        ? describeSpawnFailure(new Error(`node could not load ${cfg.egoBin}`))\n        : `ego-browser exited with ${\n            outcome.exitCode !== null\n              ? `code ${outcome.exitCode}`\n              : `signal ${String(outcome.signal)}`\n          }${describeStderr(stderr)}`,\n      stdout,\n      stderr,\n    }\n  }\n  const value = parseSentinel(mergeCliOutput({ stdout, stderr }))\n  // A script that prints ordinary output and no payload has still run: the\n  // sentinel only enriches the result, so the exit code above stays the\n  // authority on success. `value` may legitimately be undefined (see toolPayload).\n  return { ok: true, value, stdout, stderr }\n}\n\n/**\n * ego-cli degraded frame source: run the poller heredoc through the SAME CLI\n * channel real tools use and resolve the merged stdout (which carries the\n * `@@BCDP_FRAME@@` payload). Kept separate from `runEgoScript` because that one\n * parses `@@DSH_RESULT@@` and needs an exec/abort context a passive poller has\n * none of. A failed or non-zero run resolves '' — the poller treats '' as \"no\n * new frame\" and keeps the previous one, so a transient cold start never blanks\n * the panel.\n */\n// A viewport PNG at up to 1920w base64-encodes to ~1.4 MB per megabyte of raw;\n// allow generous headroom so the reader never truncates the frame payload.\nconst CLI_FRAME_MAX_BYTES = 12 * 1024 * 1024\n/** Outcome of the most recent ego-cli frame capture, for bcdp_doctor diagnosis. */\nexport interface CliFrameDiag {\n  at: number\n  exitCode: number | null\n  stdoutLen: number\n  hasSentinel: boolean\n  stderrTail: string\n}\nlet lastCliFrameDiag: CliFrameDiag | null = null\n/** @internal last ego-cli frame capture diagnostic (null until one runs). */\nexport function getCliFrameDiag(): CliFrameDiag | null { return lastCliFrameDiag }\n/**\n * Which task space a host-initiated ego-cli script should drive.\n *\n * Both the passive frame poller and the panel actions (size sync / navigate)\n * must observe the SAME space the calling session's tools act on, so the rule\n * lives in one place: use the tracker's last active space, and when it lagged\n * (no tool has run yet in this session) derive the per-session namespace\n * `dsh-agent-<sid8>` from the persisted current session. A global/unknown\n * session yields null: the caller then skips rather than binding the shared\n * `default` slot.\n * @internal exported for tests\n */\nexport function resolveCliPanelSpace(\n  cfg: EgoRuntimeConfig,\n  space?: string | number | null,\n): string | number | null {\n  let next = space ?? cfg.spaceTracker.lastActiveSpace()\n  if (next === null || next === undefined || next === '') {\n    const sid = cfg.spaceTracker.currentSession()\n    if (sid !== undefined && sid !== '' && sid !== GLOBAL_SESSION_KEY) {\n      next = deriveSlotDefaultName(\n        { defaultSpace: cfg.defaultSpace, isolateSpaces: cfg.isolateSpaces },\n        sid,\n      )\n    }\n  }\n  return next === null || next === undefined || next === '' ? null : next\n}\n\n/**\n * ego-cli panel actions (size sync / presets / maximize / refresh / URL).\n *\n * The CDP-worker route answers /api/window-size + /api/navigate natively; an\n * `ego-cli` link injects no websocket, so the same two operations run as short\n * heredocs on the exact channel real tools use (see cast/panel-actions.ts).\n * Serialized behind the plugin lock so a drag never races a tool call, and the\n * poller (which skips while busy) cannot screenshot a half-resized window.\n */\nfunction makePanelActions(ctx: EgoContext, cfg: EgoRuntimeConfig): PanelActionRunner {\n  const run = (build: (spaceJson: string) => string): Promise<PanelActionOutcome> => {\n    const space = resolveCliPanelSpace(cfg)\n    if (space === null) {\n      return Promise.resolve({ ok: false, error: 'no agent browser page yet — run a bcdp_* tool to open one first' })\n    }\n    const script = build(j(space))\n    return withEgoLock(async () => {\n      const result = await runEgoScript(ctx.subprocess, script, {}, cfg)\n      const parsed = parsePanelResult(mergeCliOutput({ stdout: result.stdout ?? '', stderr: result.stderr ?? '' }))\n      if (parsed !== null) return parsed\n      return { ok: false, error: result.error ?? 'panel action produced no result (ego-cli sentinel missing)' }\n    })\n  }\n  return {\n    windowSize: (body) => run((spaceJson) => buildEgoWindowSizeScript(spaceJson, body)),\n    navigate: (body) => run((spaceJson) => buildEgoNavigateScript(spaceJson, body)),\n    switchTab: (body) => run((spaceJson) => buildEgoSwitchTabScript(spaceJson, body)),\n  }\n}\n\n/** Shape the panel needs for one Tabbit tab (same contract as an ego/CDP space). */\nexport interface TabbitSpaceRow {\n  targetId: string\n  url: string\n  title: string\n  active: boolean\n  lastActive: number\n  /** Which browser window this tab belongs to (panel shows a W1/W2 badge). */\n  windowId?: number\n}\n\n/**\n * Tabbit's available tabs, for the panel's shared tab bucket.\n *\n * The 3s inventory poller already caches them (`_tabbitTabCache`); the watch\n * panel had no idea they existed, so a Tabbit session showed an empty strip and\n * nothing to @-quote. Rows use the CLI's `tabId` as targetId so a quote can be\n * traced back to the exact tab.\n */\nexport function tabbitSpaceRows(scope: 'window' | 'all' = 'all'): { tabs: TabbitSpaceRow[]; updatedAt: number; complete: boolean } {\n  const updatedAt = _tabbitTabCache.updatedAt\n  // The strip lists EVERY window's tabs by default (\"最全\"): a user with two\n  // Tabbit windows was being shown one window and reading it as \"tabs missing\".\n  // Window scoping still decides WHICH tab gets captured / activated — see\n  // _tabbitWindowId — it just no longer hides rows.\n  const scoped = scope === 'all' || _tabbitWindowId === 0\n    ? _tabbitTabCache.tabs\n    : _tabbitTabCache.tabs.filter((t) => (t.windowId ?? 0) === _tabbitWindowId)\n  const rows = scoped.length > 0 ? scoped : _tabbitTabCache.tabs\n  return {\n    tabs: rows.map((t) => ({\n      targetId: String(t.tabId),\n      url: t.url || '',\n      title: t.title || '',\n      active: t.active === true,\n      lastActive: updatedAt,\n      windowId: t.windowId ?? 0,\n    })),\n    updatedAt,\n    complete: _tabbitTabCache.complete,\n  }\n}\n\n/**\n * 把「本轮真的有图」的那个 tab 标成 active 行。\n *\n * 不是美化：客户端 `renderSpaces` 在仅激活模式下只保留 `active === true` 那一行，\n * 然后拿这份名单去淘汰 `frameCache`。而 CLI 给的 `active` 是**浏览器 MRU tab**，\n * 轮询拍的却是 **agent 正在驱动的那个 tab**——两者不一致时，刚拍到的帧会被当场\n * 逐出，视图又切到一个从没拍过的行（“无截图”）；1s 心跳重播把帧塞回来，下个\n * 3s `spaces` 再逐出——就是每轮一次的画/空闪跳。把主拍 tab 标为 active 后，\n * 面板跟随的行永远有图。\n *\n * primaryTargetId 为空或在名单里找不到时原样返回（保持旧行为兼容，不凭空造 active）。\n */\nexport function rowsWithPrimaryActive(rows: readonly TabbitSpaceRow[], primaryTargetId: string): TabbitSpaceRow[] {\n  if (primaryTargetId === '' || !rows.some((r) => r.targetId === primaryTargetId)) return [...rows]\n  return rows.map((r) => (r.targetId === primaryTargetId ? { ...r, active: true } : { ...r, active: false }))\n}\n\n/** Error carrying the envelope code the gateway maps to a status. */\nfunction codedError(code: string, message: string): Error {\n  return Object.assign(new Error(message), { code })\n}\n\n/**\n * Tab-anchor report for the routes that own no CDP websocket.\n *\n * The CDP route reads the Accessibility tree over a socket; ego-cli and Tabbit\n * cannot, so both collect interactive candidates with the SAME in-page DOM scan\n * (`cast/fallback-tab-report.ts`) and hand them to the CDP path's own numbering\n * + anchor helpers. A route that cannot read the page at all still returns a\n * URL+title report marked degraded — an @ object with no elements beats a 409.\n */\nfunction makeFallbackTabReport(ctx: EgoContext, cfg: EgoRuntimeConfig): (input: { targetId: string; urlHint: string; titleHint: string }) => Promise<TabAnchorReport> {\n  return async (input) => {\n    const { effective } = effectiveChannel(cfg)\n    // Tabbit is the only channel without the ego runtime AND with its own AX\n    // snippet, so the capability answers the question the kind used to.\n    if (runtimeOfLink(effective?.link)?.channel.egoRuntime === false) {\n      const cli = resolveTabbitCli((effective?.link as { cliPath?: string } | undefined)?.cliPath)\n      if (!cli.found) throw codedError('cli-not-found', `tabbit-cli not found: ${cli.error}`)\n      const tabId = Number(input.targetId)\n      const { receipt } = await runTabbitSnippet(ctx.subprocess, buildTabbitAxSnippet(), {\n        cliPath: cli.cliPath,\n        taskName: _tabbitLastTaskName || 'dsh-browser-cdp',\n        requestId: `anchor-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,\n        timeoutMs: 120000,\n        ...(Number.isFinite(tabId) && tabId > 0 ? { tabId } : {}),\n      })\n      if (!receipt.ok) {\n        return composeFallbackReport({\n          route: 'tabbit-cli',\n          targetId: input.targetId,\n          degraded: 'tabbit-cli',\n          snapshot: { url: input.urlHint, title: input.titleHint, targetId: input.targetId, nodes: [] },\n        }) as TabAnchorReport\n      }\n      const data = (receipt.data || {}) as { url?: unknown; title?: unknown; nodes?: unknown }\n      const snapshot: FallbackAxSnapshot = {\n        url: str(data.url, input.urlHint),\n        title: str(data.title, input.titleHint),\n        targetId: input.targetId,\n        nodes: Array.isArray(data.nodes) ? (data.nodes as { role: string; name: string }[]) : [],\n      }\n      return composeFallbackReport({ route: 'tabbit-cli', targetId: input.targetId, snapshot }) as TabAnchorReport\n    }\n    if (runtimeOfLink(effective?.link)?.channel.frames === 'ego-cli-poll') {\n      const space = resolveCliPanelSpace(cfg)\n      if (space === null) throw codedError('attach-not-ready', 'no agent browser space yet — open a page with a bcdp_* tool first')\n      const result = await withEgoLock(() => runEgoScript(ctx.subprocess, buildEgoAxScript(j(space)), {}, cfg))\n      const parsed = parseAxSentinel(mergeCliOutput({ stdout: result.stdout ?? '', stderr: result.stderr ?? '' }))\n      if (parsed === null || parsed.ok !== true) {\n        return composeFallbackReport({\n          route: 'ego-cli',\n          targetId: input.targetId,\n          degraded: 'ego-cli',\n          snapshot: { url: input.urlHint, title: input.titleHint, targetId: input.targetId, nodes: [] },\n        }) as TabAnchorReport\n      }\n      return composeFallbackReport({\n        route: 'ego-cli',\n        targetId: input.targetId,\n        snapshot: {\n          url: parsed.url ?? input.urlHint,\n          title: parsed.title ?? input.titleHint,\n          targetId: parsed.targetId || input.targetId,\n          nodes: parsed.nodes ?? [],\n        },\n      }) as TabAnchorReport\n    }\n    throw codedError('attach-not-ready', 'no live CDP attach and no CLI fallback for this link kind')\n  }\n}\nasync function spawnCliFrameCapture(\n  subprocess: SubprocessService,\n  cfg: EgoRuntimeConfig,\n  space: string | number | null,\n): Promise<string> {\n  // No session-scoped browser activity yet → do NOT spawn and do NOT bind a\n  // space (that is what previously registered/screenshotted the shared\n  // `default`). The poller keeps the previous frame (none) and the panel shows\n  // its placeholder until the agent actually opens a page in its own space.\n  space = resolveCliPanelSpace(cfg, space)\n  if (space === null) return ''\n  const { attach } = effectiveChannel(cfg)\n  // 全模式: capture every tab in the space (one heredoc, one image per tab) so\n  // the panel can show a live picture per tab. 仅激活: one image, as before.\n  // The persisted setting is the default; a panel toggle overrides it for this\n  // host session (see getCliTrackAll).\n  const script = buildFrameScript(j(space), { all: getCliTrackAll(cfg.tabTracking === 'all') })\n  try {\n    const handle = subprocess.spawn({\n      argv: buildEgoToolArgv(cfg.egoArgvPrefix, attach, cfg.runtimeArgs ?? ''),\n      cwd: process.cwd(),\n      env: resolveEgoEnv(cfg),\n      stdio: {\n        stdin: { data: script },\n        stdout: { maxBytes: CLI_FRAME_MAX_BYTES, spill: { maxBytes: CLI_FRAME_MAX_BYTES } },\n        stderr: { maxBytes: CLI_FRAME_MAX_BYTES, spill: { maxBytes: CLI_FRAME_MAX_BYTES } },\n      },\n      graceMs: cfg.graceMs,\n    })\n    const outcome = await handle.done\n    const stdout = readAll(handle.collected.stdout)\n    const stderr = readAll(handle.collected.stderr)\n    const merged = mergeCliOutput({ stdout, stderr })\n    // Record WHY a capture produced (or did not produce) a frame, so bcdp_doctor\n    // can explain a poller stuck at seq 0 without a live debugger.\n    lastCliFrameDiag = {\n      at: Date.now(),\n      exitCode: typeof outcome.exitCode === 'number' ? outcome.exitCode : null,\n      stdoutLen: stdout.length,\n      hasSentinel: merged.includes(FRAME_SENTINEL),\n      stderrTail: stderr.slice(-300),\n    }\n    // Do NOT drop a usable frame on a non-zero exit code: the ego CLI can print\n    // the frame sentinel yet still exit non-zero (trailing cleanup/asserts), and\n    // the old `exitCode !== 0 -> ''` gate silently discarded every such frame.\n    // The poller's parseFrameSentinel already validates presence + base64, so\n    // returning the merged output is safe: absent/invalid payload = no frame.\n    return merged\n  } catch {\n    return ''\n  }\n}\n// ── tool plumbing ───────────────────────────────────────────────────────────\n/** How much raw stdout a tool may hand back when a script emitted no JSON. */\nconst TOOL_RAW_STDOUT_MAX = 4000\n/**\n * The payload a bcdp_* tool returns for a successful run.\n *\n * Dropping `undefined` straight into the tool result would show the model an\n * empty outcome for a script that actually ran, so fall back to the (bounded)\n * raw stdout plus a note naming the reason. Structured tools always emit a\n * sentinel payload and never take this branch.\n */\nfunction toolPayload(result: WarmupResult): unknown {\n  if (result.value !== undefined) return result.value\n  return {\n    ok: true,\n    stdout: (result.stdout ?? '').trim().slice(0, TOOL_RAW_STDOUT_MAX),\n    note: 'no JSON payload on stdout; raw output returned',\n  }\n}\n/** JS snippet that pins an action tool to one task space. */\nconst useSpace = (name: string | number): string =>\n  `const task = await taskSpaces.useOrCreate(${j(name)})\\n`\n/**\n * JS snippet that makes the harness act on a real page tab.\n *\n * The Linux host (PR #234 ego-linux) does not reliably persist \"current tab\"\n * across CLI invocations: a fresh process sometimes resolves page actions\n * against a blank/stale tab. Selecting the first non-blank tab in the space\n * before acting makes cross-process tool calls deterministic.\n *\n * #96: never re-activate a tab that is already active — Target.activateTarget\n * restores a minimized Chrome window on Windows, so every tool call would pop\n * the browser back up. Only a pinned/background target needs the switch.\n *\n * A fixed viewport (viewportWidth/Height/deviceScaleFactor) is applied AFTER the\n * tab is selected, because cdp() needs an attached session and there is no tab\n * to attach to before the first one exists. The override is emitted on every\n * call because a one-shot heredoc process dies with the call.\n */\nexport interface ViewportSpec {\n  viewportWidth?: number\n  viewportHeight?: number\n  deviceScaleFactor?: number\n}\n/** Viewport applied by `ensureRealTab()` for the current buildScript call. */\nlet pendingViewport: ViewportSpec | undefined\nconst viewportPrelude = (spec: ViewportSpec): string => {\n  const width = Math.round(spec.viewportWidth ?? 0)\n  const height = Math.round(spec.viewportHeight ?? 0)\n  if (!(width > 0) || !(height > 0)) return ''\n  const scale = spec.deviceScaleFactor !== undefined && spec.deviceScaleFactor > 0 ? spec.deviceScaleFactor : 1\n  return `if (__real) { try { await cdp('Emulation.setDeviceMetricsOverride', { width: ${width}, height: ${height}, deviceScaleFactor: ${scale}, mobile: false }) } catch {} }\\n`\n}\nconst ensureRealTab = (): string =>\n  `const __tabs = await browser.listTabs()\\n` +\n  `const __blank = (u) => /^(about:|chrome:|chrome-extension:|edge:|devtools:|data:)/.test(String(u || ''))\\n` +\n  `const __real = __tabs.find(t => t.active === true && !__blank(t.url))\\n` +\n  `  ?? __tabs.find(t => !__blank(t.url))\\n` +\n  `  ?? __tabs.find(t => t.active === true)\\n` +\n  `  ?? __tabs[0]\\n` +\n  `if (__real && __real.active !== true) await browser.switchTab(__real.targetId)\\n` +\n  (pendingViewport !== undefined ? viewportPrelude(pendingViewport) : '')\n/**\n * G �?a raw heredoc (`bcdp_script` with verbatim:true) that touches `page.*` without\n * first selecting a task space dies with the runtime's \"no active tab to attach\n * session\". Structured bcdp_* tools never hit this because each wraps its body\n * in `useSpace(...)` + `ensureRealTab()`; a hand-written heredoc has no such\n * preamble. Detect the signature and append a one-line how-to-fix, so the error\n * names the escape (call `taskSpaces.useOrCreate(name)` first) instead of\n * leaving the model to rediscover it.\n * @internal exported for tests\n */\nexport const ATTACH_SESSION_HINT =\n  'hint: call `await taskSpaces.useOrCreate(name)` (and `browser.switchTab(...)` if the space has no real tab) before using page.* in a raw heredoc — structured bcdp_* tools do this for you.'\nexport function attachSessionHint(errorText: string | undefined): string {\n  const t = errorText ?? ''\n  if (!/no active tab to attach session/.test(t)) return t\n  return t.includes(ATTACH_SESSION_HINT) ? t : `${t}\\n${ATTACH_SESSION_HINT}`\n}\n\nfunction renderText(_args: unknown, value: unknown): unknown[] {\n  const v = value as Record<string, unknown> | null\n  if (\n    v !== null &&\n    typeof v === 'object' &&\n    v.ok === true &&\n    typeof v.text === 'string'\n  ) {\n    return [{ type: 'text', text: v.text }]\n  }\n  return [{ type: 'text', text: JSON.stringify(value, null, 2) }]\n}\nconst commonOutputSchema = {\n  type: 'object',\n  additionalProperties: true,\n  properties: {\n    ok: { type: 'boolean', required: true },\n  },\n}\n\n/**\n * The calling session id �?the scope the client's sidebar auto-open binds to.\n * Read structurally (`exec.agent` is typed `unknown` in this plugin's own\n * seam); a call with no initiating agent simply leaves the open unscoped.\n */\n/**\n * Move the operation focus to whatever tab the tool just reported.\n *\n * Deliberately best-effort: a tool that does not carry a target id simply does\n * not move anything, and a worker that answers `focus-stale` clears it rather\n * than pinning a dead row (see pushFocus in cast-server).\n */\nfunction noteToolFocus(value: unknown): void {\n  const targetId = focusIdFrom(value)\n  if (targetId === null) return\n  void pushFocus(targetId, 'agent').catch(() => null)\n}\n\nfunction callingSessionId(exec: ToolExec | undefined): string | undefined {\n  const agent = exec?.agent as { session?: { id?: unknown } } | undefined\n  const id = agent?.session?.id\n  return typeof id === 'string' && id !== '' ? id : undefined\n}\n\ninterface EgoToolOptions {\n  name: string\n  description: string\n  parameters: Record<string, unknown>\n  buildScript: (args: Record<string, unknown>) => string\n  afterExecute?: (args: Record<string, unknown>, value: unknown) => void\n  /** F: wrap this tool's run in the tab-revive watchdog and tag recoveredFrom. */\n  tabRevive?: boolean\n  /** Lightpanda backend �?return a blocking reason (or null to allow) checked BEFORE any runtime spawn. */\n  gate?: (args: Record<string, unknown>) => string | null\n}\n\n/**\n * Tabbit tab inventory cache (module-level, written by 3s poller, read by tool handlers).\n * @internal\n */\nconst _tabbitTabCache: { tabs: TabbitTab[]; total: number; complete: boolean; updatedAt: number } = { tabs: [], total: 0, complete: false, updatedAt: 0 }\n/**\n * Which browser WINDOW the panel shows.\n *\n * Tabbit reports every tab of every window. Two windows that happen to hold the\n * same two pages then look like DUPLICATED tabs in the strip (“全模式双重” bug).\n * The agent works in one window, so the strip follows that window: the one\n * holding the tab the agent last drove, else the browser's focused window.\n * 0 = unscoped (fall back to every tab).\n */\nlet _tabbitWindowId = 0\n\n/**\n * Task name the PANEL owns when no tool call has established one.\n *\n * Screenshots used to be gated on the conversation: no `bcdp_*` → no task →\n * `no-owner` → empty frame forever. The panel now adopts this name as soon as\n * somebody watches it, and tool calls reuse whatever owner already exists — so\n * frames and tools still share exactly one tabbit task.\n */\nconst TABBIT_PANEL_TASK = 'dsh-panel'\n/** Upper bound on pages one task may own; each extra page slows every call. */\nconst TABBIT_MAX_OWNED_PAGES = 2\n/** Last close attempt, echoed in the stats snapshot: the panel's × is verified by\n * INVENTORY, not by the receipt status (page.close() kills the receipt). */\nlet lastClose: { tabId: number; task: string; state: string; status: string; closedByReceipt: boolean; stillThere: boolean; ms: number; at: number } | null = null\n/** A close is in flight: the poller must yield the executor or the receipt queues. */\nlet _closeInFlight = false\n/** On-demand capture single-flight (see captureTabbitTab). */\nlet _tabbitShotInFlight = false\n/**\n * tabId → task that OWNS it, refreshed from `diagnose`.\n *\n * Ownership is per task and `--tab` must run as the owner: a tab owned by\n * `dsh-panel` answers `TAB_OWNERSHIP_CONFLICT` to any other task, which is why\n * both close AND capture failed while the panel task held every tab. Cached for a\n * few seconds because `diagnose` is a process spawn and the tick runs every 3 s.\n */\nlet _tabbitOwnerCache: { at: number; owners: Map<number, string> } = { at: 0, owners: new Map() }\n\n/**\n * Which task owns `tabId`, cached for 20 s.\n *\n * `--tab` must run as the owner or tabbit answers `TAB_OWNERSHIP_CONFLICT` — the\n * single reason both the panel's × and its per-tab capture silently died while\n * `dsh-panel` held every tab.\n */\nasync function tabbitOwnerOf(ctx: EgoContext, cliPath: string, tabId: number): Promise<string> {\n  const now = Date.now()\n  if (now - _tabbitOwnerCache.at > 20_000) {\n    try {\n      const diag = await tabbitDiagnose(ctx.subprocess, cliPath)\n      const owners = new Map<number, string>()\n      for (const task of parseTabbitTasks(diag.raw)) {\n        for (const id of task.ownedTabIds) owners.set(id, task.taskName)\n      }\n      _tabbitOwnerCache = { at: now, owners }\n    } catch {\n      // Keep the previous map and push the TTL out so we do not retry every tick.\n      _tabbitOwnerCache = { at: now, owners: _tabbitOwnerCache.owners }\n    }\n  }\n  return _tabbitOwnerCache.owners.get(tabId) ?? ''\n}\n\n/**\n * Keep the panel task's ownership at ONE page.\n *\n * Every `nodejs --tab <id>` ADDS the tab to the task's owned set, and tabbit waits\n * for ALL owned pages to attach before running the snippet. A panel that captured\n * its way through nine tabs therefore hit `PAGE_ATTACHMENT_TIMEOUT` after 30 s on\n * every single call — measured: \"Timed out waiting for 9 owned Playwright Pages\".\n * `finish` (keep) releases them without closing anything, so the next capture\n * re-acquires exactly the tab it needs (108 ms in the same test).\n */\nasync function releaseOverOwnedPanelTask(ctx: EgoContext, cliPath: string): Promise<void> {\n  if (_tabbitLastTaskName !== TABBIT_PANEL_TASK) return\n  const owned = [..._tabbitOwnerCache.owners.values()].filter((name) => name === TABBIT_PANEL_TASK).length\n  // Cap at 6, not 1: one `context.pages()` call captures every owned page, so a\n  // larger owned set is exactly what gives background tabs their pictures. Six is\n  // the old ego-route上限 per round, and beyond it every call waits for one more\n  // page to attach (that is what produced PAGE_ATTACHMENT_TIMEOUT with nine).\n  if (owned <= TABBIT_MAX_OWNED_PAGES) return\n  await tabbitFinishTask(ctx.subprocess, cliPath, TABBIT_PANEL_TASK, false).catch(() => undefined)\n  _tabbitOwnerCache = { at: 0, owners: new Map() }\n}\n/** When the last panel watcher disappeared (0 = someone is watching). */\nlet _tabbitWatcherGoneAt = 0\n\n/**\n * The last tab ID the agent actively operated on (set by navigate/acquire).\n * The frame poller uses this to screenshot the correct page.\n * @internal\n */\nlet _tabbitLastActiveTabId: number | null = null\n/**\n * The task name used by the last tool call (frame poller must reuse it to access owned tabs).\n * @internal\n */\nlet _tabbitLastTaskName: string = ''\n\n/**\n * Tabbit backend dispatcher: when the active link is tabbit-cli, route the tool\n * call through tabbit-cli nodejs instead of the ego SDK subprocess path.\n * Returns {ok, ...data} matching toolPayload contract, or null to fall through\n * to the ego path (e.g. non-tabbit links, unsupported tools).\n */\n/**\n * The per-task receipt budget (measured: 1024, and a full task fails EVERY\n * `nodejs` run with empty stdout). Tracked locally because we create exactly\n * one receipt per run; asked nowhere else because that would cost another\n * subprocess. Recycled at 80% so the caller never sees the wall.\n */\nconst tabbitReceipts = createReceiptLedger()\n/** Set inside apply() so a recycle can also drop the frame poller's local rows. */\nlet tabbitOnRecycle: (() => void) | null = null\n\n/** Tab ids and rows belong to the finished task; nothing from it survives. */\nfunction forgetTabbitTaskState(): void {\n  _tabbitTabCache.tabs = []\n  _tabbitTabCache.total = 0\n  _tabbitTabCache.complete = false\n  _tabbitTabCache.updatedAt = 0\n  _tabbitWindowId = 0\n  _tabbitLastActiveTabId = null\n  try { tabbitOnRecycle?.() } catch { /* ignore */ }\n}\n\n/**\n * Hand the task back (tabs retained: `finish` without `--discard`) and forget\n * it. The next `nodejs` run recreates the task on demand — measured to work,\n * which is what makes this a caller-invisible operation.\n */\nasync function recycleTabbitTask(subprocess: SubprocessService, cliPath: string, taskName: string): Promise<boolean> {\n  try {\n    await tabbitFinishTask(subprocess, cliPath, taskName, false)\n  } catch {\n    return false\n  }\n  tabbitReceipts.reset(taskName)\n  tabbitReceipts.noteRecycle()\n  forgetTabbitTaskState()\n  return true\n}\n\n/**\n * Every tabbit run goes through here.\n *\n * The frame poller used to burn the whole budget on its own (one receipt every\n * 3 s, ~51 min per tab), so the WATCH PANEL starved the TOOL PATH and nothing\n * could heal: the CLI keeps receipts and the old code never recycled. Now the\n * budget is counted, recycled before the wall, and retried once when the wall\n * is already hit.\n */\nasync function runTabbitSnippet(\n  subprocess: SubprocessService,\n  jsCode: string,\n  opts: Parameters<typeof runTabbitSnippetRaw>[2],\n): Promise<Awaited<ReturnType<typeof runTabbitSnippetRaw>>> {\n  const task = opts.taskName\n  if (tabbitReceipts.needsRecycle(task)) {\n    // Proactive: recycle BEFORE the wall so this call does not fail at all.\n    const recycled = await recycleTabbitTask(subprocess, opts.cliPath, task)\n    if (recycled) ctx_logTabbitRecycleHint(task, 'proactive')\n  }\n  tabbitReceipts.note(task)\n  let out = await runTabbitSnippetRaw(subprocess, jsCode, opts)\n  if (out.receipt.ok) return out\n  const empty = out.receipt.error?.code === 'EMPTY_OUTPUT'\n  const used = tabbitReceipts.count(task)\n  if (empty && used + 1 >= TABBIT_RECYCLE_AT) {\n    if (await recycleTabbitTask(subprocess, opts.cliPath, task)) {\n      tabbitReceipts.note(task)\n      out = await runTabbitSnippetRaw(subprocess, jsCode, { ...opts, requestId: `${opts.requestId}-r` })\n      if (out.receipt.ok) return out\n    }\n  }\n  if (!empty) return out\n  return {\n    ...out,\n    receipt: {\n      ...out.receipt,\n      error: {\n        code: 'tabbit-task-stalled',\n        message: `${out.receipt.error?.message ?? 'no stdout'} (task receipts ${used}/${TABBIT_RECEIPT_QUOTA}; finish+recreate attempted — if this persists, close the agent page with bcdp_space op=close)`,\n      },\n    },\n  }\n}\n\n/** Logged once per recycle, through the only logger this module can reach. */\nfunction ctx_logTabbitRecycleHint(task: string, why: string): void {\n  process.stderr.write(`[dsh-browser-cdp] tabbit task recycled (${why}): ${task} — receipts ${TABBIT_RECEIPT_QUOTA} budget, ${tabbitReceipts.recycles()} recycle(s)\\n`)\n}\n\nasync function tryTabbitExecute(\n  ctx: EgoContext,\n  cfg: EgoRuntimeConfig,\n  toolName: string,\n  args: Record<string, unknown>,\n  taskName: string,\n): Promise<unknown | null> {\n  const { effective } = effectiveChannel(cfg)\n  if (!effective || runtimeOfLink(effective.link)?.channel.egoRuntime !== false) return null\n  const cli = resolveTabbitCli((effective.link as any).cliPath)\n  if (!cli.found) return { ok: false, text: `tabbit-cli not found: ${cli.error}` }\n  const sub = ctx.subprocess\n  // Record task name for frame poller (must reuse same task to access owned tabs).\n  // `bcdp_status` 不登记：它只做 diagnose，不拥有任何 tab。早期版本 status 不走本函数，\n  // 轮询器因此只在首个真实浏览动作后才启动；若让一次状态查询就点亮轮询，面板会在\n  // 还没有 agent 页面时就开始抓用户自己的 tab。\n  if (toolName !== 'bcdp_status') _tabbitLastTaskName = taskName\n  const reqId = `${toolName}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`\n  // Every run reports the tab(s) it acquired. Remember the last one so the frame\n  // poller screenshots THAT page instead of the task's default about:blank.\n  const trackRun = (receipt: { tabIds?: number[] }): void => {\n    const ids = receipt.tabIds\n    if (ids && ids.length > 0) _tabbitLastActiveTabId = ids[ids.length - 1]!\n  }\n\n  switch (toolName) {\n    // `bcdp_status` 由宿主侧的 registerEgoStatus 在 tabbit 激活时显式转发到这里；\n    // `bcdp_help` / `bcdp_doctor` 两个 case 目前仍不可达（同为宿主侧 defineTool，\n    // 自己的 execute 不经过本分派闸）。保留是为了日后改回 t() 注册时行为仍正确；\n    // 改动时请一并核对。\n    case 'bcdp_status': {\n      // Report tabbit backend status: try diagnose (gives browser time to launch)\n      const diag = await tabbitDiagnose(sub, cli.cliPath)\n      return { ok: diag.reachable, available: diag.reachable, backend: 'tabbit-cli', raw: diag.raw.slice(0, 500), path: cli.cliPath }\n    }\n    case 'bcdp_help': {\n      return {\n        ok: true,\n        text: [\n          `Tabbit backend active (${cli.cliPath}).`,\n          `Supported tools (${TABBIT_CLI_SUPPORTED.length}): ${TABBIT_CLI_SUPPORTED.join(', ')}.`,\n          'Not available on this backend (sealed from the tool list): bcdp_cdp, bcdp_key, bcdp_scroll, hover/select/check/drag, bcdp_wait, upload/download/dialog, captcha/auth/login_import, bcdp_jev_*.',\n          'Fallback: bcdp_js for a single expression (e.g. window.scrollBy(0,600)), bcdp_script for multi-step work.',\n          'Unsupported tools return errors (no ego fallback).',\n        ].join('\\n'),\n        backend: 'tabbit-cli',\n      }\n    }\n    case 'bcdp_doctor': {\n      const diag = await tabbitDiagnose(sub, cli.cliPath)\n      return { ok: true, text: `backend: tabbit-cli\\ncliPath: ${cli.cliPath}\\nreachable: ${diag.reachable}\\nraw: ${diag.raw.slice(0, 300)}`, backend: 'tabbit-cli' }\n    }\n    case 'bcdp_space': {\n      const op = str(args.op, 'open')\n      if (op === 'open') {\n        const inv = await tabbitCreateTask(sub, cli.cliPath, taskName)\n        return { ok: true, ...inv, backend: 'tabbit-cli' }\n      }\n      if (op === 'close') {\n        await tabbitFinishTask(sub, cli.cliPath, taskName, Boolean(args.discard))\n        return { ok: true, released: true, backend: 'tabbit-cli' }\n      }\n      if (op === 'list') {\n        const diag = await tabbitDiagnose(sub, cli.cliPath)\n        return { ok: diag.reachable, raw: diag.raw, backend: 'tabbit-cli' }\n      }\n      return { ok: false, text: `bcdp_space: unsupported op=${op} on tabbit backend` }\n    }\n    case 'bcdp_tab': {\n      const op = str(args.op, 'list')\n      if (op === 'list') {\n        // Read from 3s poller cache if fresh (<5s), else live-fetch.\n        if (Date.now() - _tabbitTabCache.updatedAt < 5000 && _tabbitTabCache.tabs.length > 0) {\n          return { ok: true, tabs: _tabbitTabCache.tabs, total: _tabbitTabCache.total, complete: _tabbitTabCache.complete, cached: true, backend: 'tabbit-cli' }\n        }\n        const stateArg = str(args.state, '') as '' | 'available' | 'owned' | 'claimed'\n        const result = await tabbitListTabs(sub, cli.cliPath, taskName, stateArg || undefined)\n        return { ok: true, ...result, backend: 'tabbit-cli' }\n      }\n      return { ok: false, text: `bcdp_tab: op=${op} not yet supported on tabbit backend` }\n    }\n    case 'bcdp_navigate': {\n      const url = str(args.url, '')\n      if (url === '') return { ok: false, text: 'bcdp_navigate: url is required' }\n      const waitUntil = str(args.waitUntil, 'domcontentloaded')\n      const js = buildNavigateSnippet(url, waitUntil)\n      const navTabId = typeof args.tab === 'number' ? args.tab : undefined\n      const { receipt } = await runTabbitSnippet(sub, js, { cliPath: cli.cliPath, taskName, requestId: reqId, timeoutMs: 120000, tabId: navTabId })\n      if (receipt.ok) {\n        // Track the tab this navigate actually ran against (frame poller target).\n        if (navTabId) _tabbitLastActiveTabId = navTabId\n        trackRun(receipt)\n        return { ok: true, ...receipt.data as object, backend: 'tabbit-playwright' }\n      }\n      if (receipt.status === 'queued' || receipt.status === 'running') {\n        const final = await pollTabbitPending(sub, { cliPath: cli.cliPath, taskName, requestId: reqId })\n        if (final.ok) {\n          trackRun(final)\n          return { ok: true, ...final.data as object, backend: 'tabbit-playwright' }\n        }\n        return { ok: false, text: `navigate pending then ${final.status}: ${final.error?.message ?? ''}` }\n      }\n      return { ok: false, text: receipt.error?.message ?? 'navigation failed' }\n    }\n    case 'bcdp_snapshot': {\n      // 厂商对 observe 的 maxChars 有硬区间（真机原错：`observe maxChars must be an\n      // integer from 256 through 20000`）。越界值会白烧一个往返，所以先夹住\n      // 并把生效值回显出去——静默改变语义比报错更难诊断。\n      const requested = typeof args.maxChars === 'number' ? args.maxChars : 8000\n      const maxChars = Math.min(20000, Math.max(256, Math.trunc(requested)))\n      const js = buildObserveSnippet(maxChars)\n      const { receipt } = await runTabbitSnippet(sub, js, { cliPath: cli.cliPath, taskName, requestId: reqId })\n      if (receipt.ok) {\n        trackRun(receipt)\n        // observe 契约把文本放在 snapshot：整个对象 String() 只会得到 [object Object]。\n        const d = receipt.data as { snapshot?: string; truncated?: boolean } | undefined\n        return {\n          ok: true,\n          text: typeof d?.snapshot === 'string' ? d.snapshot : '',\n          ...(d?.truncated === true ? { truncated: true } : {}),\n          ...(maxChars !== requested ? { maxCharsUsed: maxChars } : {}),\n          ...(receipt.dataTruncated === true ? TABBIT_OVERFLOW_HINT : {}),\n          format: 'plaintext',\n          backend: 'tabbit-playwright',\n        }\n      }\n      return { ok: false, text: receipt.error?.message ?? 'observe failed' }\n    }\n    case 'bcdp_click': {\n      const selector = str(args.selector, str(args.loc, ''))\n      const plan = translateLocator(selector)\n      if (!plan) return { ok: false, text: `bcdp_click: cannot resolve selector \"${selector}\" on the tabbit backend (use loc=role:…, loc=css:…, loc=href:…, or a snapshot ref like @e3)` }\n      const js = buildClickSnippet(plan)\n      const { receipt } = await runTabbitSnippet(sub, js, { cliPath: cli.cliPath, taskName, requestId: reqId })\n      if (receipt.ok) { trackRun(receipt); return { ok: true, ...receipt.data as object, backend: 'tabbit-playwright' } }\n      return { ok: false, text: receipt.error?.message ?? 'click failed' }\n    }\n    case 'bcdp_fill': {\n      const selector = str(args.selector, str(args.loc, ''))\n      // 工具面的必填名是 `text`（ego 分支同样读 text）；早先这里只读 value，\n      // 等于 tabbit 路线上 fill 永远填一段空串。\n      const value = str(args.text, str(args.value, ''))\n      const plan = translateLocator(selector)\n      if (!plan) return { ok: false, text: `bcdp_fill: cannot resolve selector \"${selector}\" on the tabbit backend (use loc=role:…, loc=css:…, loc=href:…, or a snapshot ref like @e3)` }\n      const js = buildFillSnippet(plan, value)\n      const { receipt } = await runTabbitSnippet(sub, js, { cliPath: cli.cliPath, taskName, requestId: reqId })\n      if (receipt.ok) { trackRun(receipt); return { ok: true, ...receipt.data as object, backend: 'tabbit-playwright' } }\n      return { ok: false, text: receipt.error?.message ?? 'fill failed' }\n    }\n    case 'bcdp_screenshot': {\n      // The CLI writes the PNG to a scratch path and returns that path; a \"path\"\n      // argument from the caller becomes that scratch file. Base64 is read back\n      // here (the receipt cannot carry it — see buildScreenshotSnippet).\n      const requested = str(args.path, '')\n      const shotPath = requested !== '' ? requested : join(tmpdir(), `dsh-browser-cdp-shot-${Date.now()}.png`)\n      const js = buildScreenshotSnippet(shotPath)\n      const { receipt } = await runTabbitSnippet(sub, js, { cliPath: cli.cliPath, taskName, requestId: reqId, timeoutMs: 120000 })\n      if (receipt.ok) {\n        trackRun(receipt)\n        const d = receipt.data as { path?: string; bytes?: number; url?: string; title?: string; skipped?: string; error?: string } | undefined\n        // A stuck capture comes back as a `skipped` marker, never as a hung call.\n        if (d?.skipped !== undefined) {\n          return { ok: false, text: `bcdp_screenshot: capture did not complete (${d.skipped}${d.error ? `: ${d.error}` : ''}) on ${d.url ?? 'unknown page'}. The page may still be loading or the renderer is not producing frames.` }\n        }\n        if (typeof d?.path !== 'string') {\n          return { ok: false, text: `bcdp_screenshot: receipt carried no path (status=${receipt.status}, data=${JSON.stringify(d ?? null).slice(0, 160)})` }\n        }\n        let base64 = ''\n        try {\n          base64 = readFileSync(d.path).toString('base64')\n        } catch (err) {\n          return { ok: false, text: `bcdp_screenshot: cannot read ${d.path}: ${String((err as Error)?.message ?? err)}` }\n        }\n        return { ok: true, path: d.path, base64, bytes: d.bytes, url: d.url, title: d.title, backend: 'tabbit-playwright' }\n      }\n      return { ok: false, text: receipt.error?.message ?? 'screenshot failed' }\n    }\n    case 'bcdp_js': {\n      const expr = str(args.expression, '')\n      if (expr === '') return { ok: false, text: 'bcdp_js: expression is required', backend: 'tabbit-playwright' }\n      const { receipt } = await runTabbitSnippet(sub, buildJsSnippet(expr), { cliPath: cli.cliPath, taskName, requestId: reqId })\n      if (receipt.ok) {\n        trackRun(receipt)\n        const d = receipt.data as { result?: unknown } | undefined\n        return { ok: true, result: d?.result ?? null, ...(receipt.dataTruncated === true ? TABBIT_OVERFLOW_HINT : {}), backend: 'tabbit-playwright' }\n      }\n      return { ok: false, text: receipt.error?.message ?? 'js evaluation failed', backend: 'tabbit-playwright' }\n    }\n    case 'bcdp_http': {\n      const url = str(args.url, '')\n      if (url === '') return { ok: false, text: 'bcdp_http: url is required', backend: 'tabbit-playwright' }\n      // server mode 走 Node 侧 fetch，snippet 运行时没有；拒绝而不是静默降级成 browser 语义。\n      if (str(args.mode, 'browser') === 'server') {\n        return {\n          ok: false,\n          text: \"bcdp_http: mode=server is unavailable on the tabbit backend (no Node-side fetch in the snippet runtime). Use mode=browser, which sends the request through page.fetch with the browser profile's cookies/CORS.\",\n          backend: 'tabbit-playwright',\n        }\n      }\n      const init: Record<string, unknown> = { method: str(args.method, 'GET').toUpperCase() }\n      if (args.headers !== undefined && typeof args.headers === 'object' && args.headers !== null) {\n        init.headers = args.headers\n      }\n      if (args.body !== undefined) init.body = str(args.body, '')\n      const { receipt } = await runTabbitSnippet(sub, buildHttpSnippet(url, init), { cliPath: cli.cliPath, taskName, requestId: reqId })\n      if (receipt.ok) {\n        trackRun(receipt)\n        // data.ok 代的是 HTTP 层结果（page.fetch 对 4xx/5xx 返回 ok:false 而非抛异常），\n        // 展开顺序保证它能覆盖外层的求值成功标记。\n        return { ok: true, ...(receipt.data as object), backend: 'tabbit-playwright' }\n      }\n      return { ok: false, text: friendlyTabbitFetchError(receipt.error?.message ?? 'http request failed'), backend: 'tabbit-playwright' }\n    }\n    case 'bcdp_script': {\n      const script = str(args.script, '')\n      if (script === '') retu