      "path": "src/jev/attempt.ts",
      "content": "/**\n * src/jev/attempt.ts — 阶段 10 追加：平的「尝试」循环（`bcdp_jev_attempt`）。\n *\n * The user's contract for this tool, verbatim:\n *\n *   「llm 给意图，选项根据 dom 生成，laya/jev 有 5 次行动的预算，\n *     决策模型花完预算或者自己选择结束则给回执」\n *\n * This is deliberately NOT the three-level narrowing loop (`loop.ts`). The\n * differences, and why they are not regressions:\n *\n *   - ONE decision per round: the option table IS the frame's DOM candidates\n *     plus one fixed `end` option. No control question (\"should we act at\n *     all\"), no chapter question — the outer LLM already decided to attempt,\n *     and the budget is the safety net instead of the control gate.\n *   - `end` is a FIRST-CLASS option the decision model can pick at any round.\n *     It is accepted WITHOUT a confidence gate: a false `end` just returns to\n *     the caller, who verifies through CDP anyway; gating it would make the\n *     model unable to stop honestly.\n *   - A candidate pick BELOW its bucket threshold is not acted on: stopping\n *     with `unclear` beats clicking on a coin flip.\n *   - The judge context is DOM-tree text only. Laya is a text classifier and\n *     cannot read the screenshot, so the image is captured and archived but\n *     never pretends to inform the decision — the state carries the SAME\n *     candidate list the option table offers (列表==表, the invariant the\n *     narrowing loop learned the hard way).\n *   - No exclusion set: every round re-captures and renumbers, so the judge\n *     always answers about the page as it is NOW.\n *\n * Every terminal state returns a receipt; nothing throws past the capture.\n */\n\nimport type { Frame, FrameNode } from './frame.ts'\nimport { anchorFor } from './anchors.ts'\nimport type { JudgeChainResult, JudgeRequest } from './judge.ts'\nimport type { IntentSpec } from './prompt.ts'\nimport { assertJudgeIsolation } from './prompt.ts'\nimport type { LoopEffects } from './loop.ts'\nimport { bucketFor, checkChoiceMargin, choice } from './wire.ts'\n\n/** Fixed question id; the judge's answer key for every round. */\nexport const ATTEMPT_QUESTION_ID = 'pick'\n/** The option key that means \"I choose to stop\". */\nexport const ATTEMPT_END_KEY = 'end'\n\nexport interface AttemptStep {\n  /** 1-based action ordinal. */\n  index: number\n  /** The frame number acted on. */\n  n: number\n  ok: boolean\n  /** What was done, in receipt prose (`click button \"OK\" [main]`). */\n  label: string\n  /** Snapshot-stable anchor of the node touched, on success only. */\n  anchor?: string\n  provider: string\n  degraded: boolean\n  /** The judge's `top` for this round's pick. */\n  top: number\n}\n\nexport type AttemptStatus =\n  | 'ended'      // the model chose `end` by itself\n  | 'exhausted'  // the action budget was spent\n  | 'blocked'    // the page offered no candidates at all\n  | 'unclear'    // a pick failed its confidence gate — refuse to act on a guess\n  | 'unavailable' // no usable judge answer\n  | 'error'      // capture threw\n\nexport interface AttemptResult {\n  status: AttemptStatus\n  reason: string\n  actions: AttemptStep[]\n  /** Candidates offered in the LAST round (0 when none). */\n  candidates: number\n  /** Identity of the last frame, for the caller's own CDP verification. */\n  lastFrameId: string\n  lastUrl: string\n}\n\nexport interface AttemptInput {\n  intent: IntentSpec\n  effects: LoopEffects\n  /** Action budget — how many element actions the model may spend. */\n  maxActions?: number\n}\n\n/** One candidate, as BOTH a FRAME list line and an option-table value. */\nfunction candidateLine(node: FrameNode): string {\n  return `${node.role} \"${node.name}\" [${node.containerLabel}]`\n}\n\nfunction endOptionText(): string {\n  return 'the goal is already achieved, or nothing on this page can advance it — stop and report back'\n}\n\nexport function buildAttemptState(frame: Frame, intent: IntentSpec, actions: readonly AttemptStep[], maxActions: number): string {\n  const nodes = frame.dom.nodes\n  const lines: string[] = []\n  lines.push('# INTENT')\n  lines.push(`goal: ${intent.goal}`)\n  for (const criterion of intent.successCriteria) lines.push(`success criterion: ${criterion}`)\n  lines.push(`actions left: ${Math.max(0, maxActions - actions.length)}`)\n  lines.push('')\n  lines.push('# FRAME')\n  lines.push(`url: ${frame.target.url}`)\n  if (frame.dom.truncated) {\n    lines.push(`(candidate list truncated: showing ${nodes.length} of ${frame.dom.total})`)\n  }\n  for (const node of nodes) lines.push(`${node.n}. ${candidateLine(node)}`)\n  if (actions.length > 0) {\n    lines.push('')\n    lines.push('# HISTORY')\n    for (const step of actions) {\n      lines.push(`${step.ok ? 'ok' : 'FAILED'}: ${step.label}`)\n    }\n  }\n  const state = lines.join('\\n')\n  // Same guard the narrowing loop uses: if a heading ever leaks in that is not\n  // one of the whitelisted sections, this throws BEFORE anything is sent.\n  assertJudgeIsolation(state)\n  return state\n}\n\nexport function attemptQuestion(nodes: readonly FrameNode[]) {  const criteria: Record<string, string> = { [ATTEMPT_END_KEY]: endOptionText() }\n  for (const node of nodes) criteria[String(node.n)] = candidateLine(node)\n  return choice(\n    'Pick the NUMBER of the element your next click should act on to advance the goal, ' +\n      `or pick \"${ATTEMPT_END_KEY}\" when it applies.`,\n    criteria,\n  )\n}\n\nexport async function runAttempt(input: AttemptInput): Promise<AttemptResult> {\n  const maxActions = input.maxActions ?? 5\n  const actions: AttemptStep[] = []\n  let lastFrameId = ''\n  let lastUrl = ''\n  let candidates = 0\n\n  for (;;) {\n    let frame: Frame\n    try {\n      const captured = await input.effects.capture()\n      frame = captured.frame\n    } catch (error) {\n      return {\n        status: 'error',\n        reason: `capture failed: ${error instanceof Error ? error.message : String(error)}`,\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n    lastFrameId = frame.frameId\n    lastUrl = frame.target.url\n    candidates = frame.dom.nodes.length\n\n    if (candidates === 0) {\n      return {\n        status: 'blocked',\n        reason: 'the DOM tree offered no interactive candidates — nothing to choose from',\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n\n    const request: JudgeRequest = {\n      questions: { [ATTEMPT_QUESTION_ID]: attemptQuestion(frame.dom.nodes) },\n      state: buildAttemptState(frame, input.intent, actions, maxActions),\n    }\n    let result: JudgeChainResult\n    try {\n      result = await input.effects.judge(request)\n    } catch (error) {\n      return {\n        status: 'unavailable',\n        reason: `the judge chain threw: ${error instanceof Error ? error.message : String(error)}`,\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n    const answer = result.answers[ATTEMPT_QUESTION_ID]\n    if (answer === undefined || answer.type !== 'choice' || typeof answer.choice !== 'string' || answer.choice === '') {\n      return {\n        status: 'unavailable',\n        reason: `no usable pick answer from ${result.provider} (chain: ${result.chain.join(' → ')})`,\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n\n    // `end` is the model's own decision to stop. Accepted without a confidence\n    // gate — see the module header.\n    if (answer.choice === ATTEMPT_END_KEY) {\n      return {\n        status: 'ended',\n        reason: 'the decision model chose to end by itself',\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n\n    const n = Number.parseInt(answer.choice, 10)\n    const node = frame.dom.nodes.find((candidate) => candidate.n === n)\n    if (node === undefined) {\n      return {\n        status: 'unclear',\n        reason: `the judge named \"${answer.choice}\", which is not an offered option`,\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n\n    // A candidate pick must clear its bucket. The table has candidates + `end`,\n    // so the bucket size is N+1, not N.\n    const bucket = bucketFor(candidates + 1)\n    const margin = checkChoiceMargin(answer, bucket.minTop, bucket.minMargin)\n    if (!margin.ok) {\n      return {\n        status: 'unclear',\n        reason: `the pick for ${node.role} \"${node.name}\" did not clear its bucket (top=${margin.top.toFixed(2)}, runner-up=${margin.runnerUp.toFixed(2)}, margin=${margin.margin.toFixed(2)}, needs top≥${bucket.minTop}${bucket.minMargin > 0 ? ` margin≥${bucket.minMargin}` : ''})`,\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n\n    const outcome = await input.effects.act({ frame, n, action: 'click' })\n    const label = `click ${node.role} \"${node.name}\" [${node.containerLabel}]`\n    actions.push({\n      index: actions.length + 1,\n      n,\n      ok: outcome.ok,\n      label: outcome.ok ? label : `${label} — failed: ${outcome.message}`,\n      provider: result.provider,\n      degraded: result.degraded,\n      top: margin.top,\n      ...(outcome.ok ? { anchor: anchorFor(frame.frameId, outcome.backendNodeId) } : {}),\n    })\n\n    if (actions.length >= maxActions) {\n      return {\n        status: 'exhausted',\n        reason: `the action budget (${maxActions}) was spent`,\n        actions,\n        candidates,\n        lastFrameId,\n        lastUrl,\n      }\n    }\n  }\n}\n"
    },
    {
      "path": "src/jev/judge.ts",
      "content": "/**\n * src/jev/judge.ts — 阶段 10: the JUDGE SEAM. This is the integration point we\n * own, and owning it is the point of the stage.\n *\n * Why a seam rather than \"just call JevLoop\": three things about JevLoop's own\n * seam are wrong for this pipeline, and each is a real defect not a preference.\n *\n *   1. Its laya provider (`backends.ts:67-72`) sends NO API key, but laya-api's\n *      `/v1/systemone` REQUIRES one — `v1.py:172` delegates to `authenticate_key`\n *      at `v1.py:27`, and there is no anonymous branch. Porting that provider\n *      verbatim means every call is a 401.\n *   2. It defaults to port 7789 while laya-api serves 8000. Also an opened-box\n *      connection error, also silent until the first request.\n *   3. Its provider resolution refuses jev without a key and then falls back to\n *      `rule` — which is correct — but the fallback is invisible in the result,\n *      so a caller cannot tell a model judgement from a heuristic one.\n *\n * So this file keeps the good idea (a provider interface with an explicit\n * preference order) and fixes the three: key and port are first-class config,\n * and every fallback is RECORDED in `degraded` + `trace`.\n *\n * ── The degradation chain, explicit and short ───────────────────────────────\n *\n *     http(jev) → http(laya) → rule → refuse\n *\n * Each hop is skipped only for a NAMED reason, and the reasons accumulate in\n * `trace[]`. `refuse` is a real outcome, not an error: returning \"the judge is\n * unavailable\" is strictly better than silently picking an element to click,\n * because a wrong click is unrecoverable while a refusal is a retry.\n *\n * ── What is deliberately NOT here ──────────────────────────────────────────\n *\n * No retry loop, no backoff, no circuit breaker. Those belong to the caller\n * that knows the deadline. This file answers \"try this provider once, tell me\n * exactly what happened\".\n */\n\nimport { type AnswerSet, type QuestionSet, type SystemOneRequest, buildSystemOneRequest, normalizeAnswers, validateQuestions } from './wire.ts'\n\n/** The canonical provider order. Index order is priority order. */\nexport const PROVIDER_ORDER = ['jev', 'laya', 'rule', 'refuse'] as const\nexport type ProviderName = (typeof PROVIDER_ORDER)[number]\n\n/** One HTTP provider's connection facts. Both fields are required, not defaults. */\nexport interface HttpProviderConfig {\n  /** Base URL WITHOUT the path, e.g. `http://127.0.0.1:8000`. */\n  baseUrl: string\n  /** Sent as `Authorization: Bearer <key>`. laya-api rejects an absent key. */\n  apiKey: string\n  /** Model field of the request body. Must be non-empty or the server rejects it. */\n  model: string\n  /** Per-attempt timeout. No retry — see the header. */\n  timeoutMs: number\n}\n\nexport interface JudgeRequest {\n  /** Which question set to ask. Keys become answer ids. */\n  questions: QuestionSet\n  /** The state the model judges. A string (the assembled prompt) or structured. */\n  state: SystemOneRequest['state']\n}\n\n/** A non-fatal fact worth surfacing: which hop was skipped and why. */\nexport interface JudgeWarning {\n  code: string\n  message: string\n  provider: string\n}\n\nexport interface JudgeUsage {\n  inputTokens?: number\n  outputTokens?: number\n  /** Raw provider payload, kept so a cost report never has to re-parse. */\n  raw?: unknown\n}\n\nexport interface JudgeResponse {\n  answers: AnswerSet\n  /** The provider that ACTUALLY answered — not the one that was preferred. */\n  provider: ProviderName\n  model: string\n  latencyMs: number\n  usage?: JudgeUsage\n  /**\n   * True when the answer did not come from the first-choice provider.\n   *\n   * This is the field JevLoop's seam lacks. `rule` is deterministic and offline\n   * but it is NOT a model judgement, and a caller that cannot tell the\n   * difference will overestimate what it was told.\n   */\n  degraded: boolean\n  /** Why the chain moved: one entry per skipped hop, in order. */\n  trace: string[]\n  warnings: JudgeWarning[]\n  /** Answer ids the provider returned malformed values for. Named, never defaulted. */\n  dropped: string[]\n  /** Answer ids the caller asked for that never came back. */\n  missing: string[]\n}\n\n/** Injected so tests never touch the network and never read a wall clock. */\nexport interface JudgeDeps {\n  fetch: typeof fetch\n  now: () => number\n}\n\nexport const defaultJudgeDeps = (): JudgeDeps => ({\n  fetch: (...args) => globalThis.fetch(...args),\n  now: () => Date.now(),\n})\n\n/**\n * The seam. One method: ask, answer, or say why not.\n *\n * Deliberately NOT `decide(intent)` — a provider must not be the place that\n * decides WHAT to ask. Assembling the question set is `prompt.ts`'s job, which\n * keeps providers swappable without re-litigating the prompt.\n */\nexport interface JudgeProvider {\n  readonly name: ProviderName\n  available(): { ok: boolean; reason: string }\n  decide(req: JudgeRequest, deps: JudgeDeps): Promise<JudgeResponse>\n}\n\n// ── the HTTP provider: jev and laya differ only in their config ─────────────\n\ninterface SystemOneEnvelope {\n  answers?: unknown\n  model?: unknown\n  usage?: unknown\n}\n\n/**\n * One HTTP judge. `jev` and `laya` are the same class with different config,\n * because they ARE the same protocol — the only differences that matter are the\n * endpoint, the key, and the model name.\n */\nexport class HttpJudgeProvider implements JudgeProvider {\n  readonly name: ProviderName\n  private readonly config: HttpProviderConfig\n\n  constructor(name: 'jev' | 'laya', config: HttpProviderConfig) {\n    this.name = name\n    this.config = config\n  }\n\n  available(): { ok: boolean; reason: string } {\n    if (this.config.baseUrl.trim() === '') return { ok: false, reason: `${this.name}-no-base-url` }\n    if (this.config.apiKey.trim() === '') {\n      // The whole reason this check exists: laya-api has no anonymous branch, so\n      // sending anyway guarantees a 401 and burns a round trip to learn nothing.\n      return { ok: false, reason: `${this.name}-no-api-key` }\n    }\n    if (this.config.model.trim() === '') return { ok: false, reason: `${this.name}-no-model` }\n    return { ok: true, reason: '' }\n  }\n\n  async decide(req: JudgeRequest, deps: JudgeDeps): Promise<JudgeResponse> {\n    const started = deps.now()\n    const issues = validateQuestions(req.questions)\n    const fatal = issues.filter((issue) => issue.code !== 'choice-criteria-over-limit')\n    if (fatal.length > 0) {\n      // Reject locally. A 422 says \"bad request\" and reads to a human as \"the\n      // model refused\", which is the most expensive kind of false signal.\n      return refuse(this.name, started, deps.now(), fatal.map((issue) => `${issue.code}:${issue.questionId}`))\n    }\n\n    const body = buildSystemOneRequest(req.state, req.questions, this.config.model)\n    const url = `${this.config.baseUrl.replace(/\\/+$/, '')}/v1/systemone`\n    const controller = new AbortController()\n    const timer = setTimeout(() => controller.abort(), this.config.timeoutMs)\n    try {\n      const response = await deps.fetch(url, {\n        method: 'POST',\n        headers: {\n          'content-type': 'application/json',\n          // Always sent. For jev this is the user's key; for laya it is the\n          // shared local key. An empty one was already caught by available().\n          authorization: `Bearer ${this.config.apiKey}`,\n        },\n        body: JSON.stringify(body),\n        signal: controller.signal,\n      })\n      if (!response.ok) {\n        return refuse(this.name, started, deps.now(), [`http-${response.status}`])\n      }\n      const payload = (await response.json()) as SystemOneEnvelope\n      const normalized = normalizeAnswers(payload.answers, Object.keys(req.questions))\n      const latencyMs = deps.now() - started\n      const warnings: JudgeWarning[] = []\n      if (normalized.dropped.length > 0) {\n        warnings.push({\n          code: 'answers-dropped',\n          message: `${this.name} returned unusable values for: ${normalized.dropped.join(', ')}`,\n          provider: this.name,\n        })\n      }\n      return {\n        answers: normalized.answers,\n        provider: this.name,\n        model: typeof payload.model === 'string' ? payload.model : this.config.model,\n        latencyMs,\n        usage: payload.usage === undefined ? undefined : { raw: payload.usage },\n        // An HTTP provider answering IS the first choice for its own slot; the\n        // caller decides whether reaching `laya` counts as degraded.\n        degraded: false,\n        trace: [],\n        warnings,\n        dropped: normalized.dropped,\n        missing: normalized.missing,\n      }\n    } catch (error) {\n      const code = controller.signal.aborted ? 'timeout' : 'network'\n      return refuse(this.name, started, deps.now(), [`${code}:${messageOf(error)}`])\n    } finally {\n      clearTimeout(timer)\n    }\n  }\n}\n\n// ── the deterministic provider: rule ────────────────────────────────────────\n\n/**\n * A rule judge: always available, never a model.\n *\n * It exists so the pipeline can run offline and in tests, and so a broken\n * endpoint degrades to something rather than nothing. It is honest about what\n * it is: every response carries `degraded: true`, because a caller that treats\n * a rule answer as a model answer will trust a heuristic far too much.\n *\n * The rules themselves are supplied by the caller rather than invented here —\n * this class is the seam, not the policy.\n */\nexport type RuleFn = (req: JudgeRequest) => AnswerSet\n\nexport class RuleJudgeProvider implements JudgeProvider {\n  readonly name: ProviderName = 'rule'\n  private readonly rule: RuleFn\n\n  constructor(rule: RuleFn) {\n    this.rule = rule\n  }\n\n  available(): { ok: boolean; reason: string } {\n    return { ok: true, reason: '' }\n  }\n\n  async decide(req: JudgeRequest, deps: JudgeDeps): Promise<JudgeResponse> {\n    const started = deps.now()\n    let answers: AnswerSet = {}\n    const warnings: JudgeWarning[] = []\n    try {\n      answers = this.rule(req)\n    } catch (error) {\n      // A throwing rule is a bug, not a degrade path — say so without hiding it.\n      warnings.push({ code: 'rule-threw', message: messageOf(error), provider: 'rule' })\n    }\n    const normalized = normalizeAnswers(answers, Object.keys(req.questions))\n    return {\n      answers: normalized.answers,\n      provider: 'rule',\n      model: 'rule',\n      latencyMs: deps.now() - started,\n      degraded: true,\n      trace: [],\n      warnings,\n      dropped: normalized.dropped,\n      missing: normalized.missing,\n    }\n  }\n}\n\n/**\n * The terminal hop. It never answers — it reports that no provider could.\n *\n * Kept as a provider rather than an exception so the chain has ONE return shape\n * and a caller cannot accidentally treat \"unavailable\" as \"no action needed\".\n * `answers` is empty and `missing` names every question that went unanswered.\n */\nexport class RefuseJudgeProvider implements JudgeProvider {\n  readonly name: ProviderName = 'refuse'\n  private readonly reasons: string[]\n\n  constructor(reasons: readonly string[]) {\n    this.reasons = [...reasons]\n  }\n\n  available(): { ok: boolean; reason: string } {\n    return { ok: true, reason: '' }\n  }\n\n  async decide(req: JudgeRequest, _deps: JudgeDeps): Promise<JudgeResponse> {\n    return {\n      answers: {},\n      provider: 'refuse',\n      model: '',\n      latencyMs: 0,\n      degraded: true,\n      trace: [...this.reasons],\n      warnings: [{ code: 'judge-unavailable', message: 'no configured provider could answer', provider: 'refuse' }],\n      dropped: [],\n      missing: Object.keys(req.questions),\n      // NOT an error: a refusal is a retryable, reportable outcome. See header.\n    }\n  }\n}\n\n// ── the chain ──────────────────────────────────────────────────────────────\n\nexport interface JudgeChainConfig {\n  jev: HttpProviderConfig | null\n  laya: HttpProviderConfig | null\n  /** The rule fallback. `null` disables the hop entirely. */\n  rule: RuleFn | null\n  /** Which providers the user has enabled. Absent = all enabled. */\n  prefer?: readonly string[]\n}\n\nexport interface JudgeChainResult extends JudgeResponse {\n  /** One line per hop: `provider:skipped` / `provider:answered` / `provider:failed`. */\n  chain: string[]\n}\n\n/**\n * Resolve the chain, then run it IN ORDER until one hop answers.\n *\n * The two behaviours worth stating explicitly:\n *\n *  - A provider that is unavailable for a NAMED reason is skipped, not called,\n *    which is how a missing key costs zero round trips instead of one 401.\n *  - A provider that is called and fails DOES fall through to the next hop, but\n *    the failure is recorded. Silent fall-through is the defect this file exists\n *    to avoid; loud fall-through is the feature.\n */\nexport class JudgeChain {\n  private readonly config: JudgeChainConfig\n  private readonly deps: JudgeDeps\n\n  constructor(config: JudgeChainConfig, deps: JudgeDeps = defaultJudgeDeps()) {\n    this.config = config\n    this.deps = deps\n  }\n\n  /** The providers in priority order, each with its availability verdict. */\n  resolve(): { provider: JudgeProvider; available: boolean; reason: string }[] {\n    const prefer = this.config.prefer ?? PROVIDER_ORDER\n    const byName = new Map<ProviderName, JudgeProvider>()\n    if (this.config.jev !== null) byName.set('jev', new HttpJudgeProvider('jev', this.config.jev))\n    if (this.config.laya !== null) byName.set('laya', new HttpJudgeProvider('laya', this.config.laya))\n    if (this.config.rule !== null) byName.set('rule', new RuleJudgeProvider(this.config.rule))\n    // `refuse` is constructed lazily by decide() from the accumulated reasons,\n    // so it has no config and is never \"unavailable\".\n\n    const out: { provider: JudgeProvider; available: boolean; reason: string }[] = []\n    for (const name of prefer) {\n      if (name === 'refuse') continue\n      const provider = byName.get(name as ProviderName)\n      if (provider === undefined) continue\n      const verdict = provider.available()\n      out.push({ provider, available: verdict.ok, reason: verdict.reason })\n    }\n    return out\n  }\n\n  async decide(req: JudgeRequest): Promise<JudgeChainResult> {\n    const chain: string[] = []\n    const trace: string[] = []\n    const warnings: JudgeWarning[] = []\n    const started = this.deps.now()\n\n    const hops = this.resolve()\n    // The first hop that was CONFIGURED is the reference for `degraded`.\n    //\n    // This must not be derived by counting `:answered` entries in `chain`.\n    // The tempting version — \"only the first answer counts as undegraded\" —\n    // is wrong in the exact case the flag exists for: jev configured but\n    // unreachable, laya answering. Then the FIRST entry is `jev:failed`, the\n    // first `:answered` is laya's, and a count-based check calls a genuine\n    // fall-through undegraded. Captured by a test that injects a per-URL fetch.\n    const firstConfigured = hops[0]?.provider.name ?? null\n\n    for (const hop of hops) {\n      if (!hop.available) {\n        chain.push(`${hop.provider.name}:skipped`)\n        trace.push(`${hop.provider.name}-skipped:${hop.reason}`)\n        warnings.push({ code: 'provider-skipped', message: hop.reason, provider: hop.provider.name })\n        continue\n      }\n\n      const response = await hop.provider.decide(req, this.deps)\n      warnings.push(...response.warnings)\n\n      if (response.provider === 'refuse') {\n        // The provider refused locally (its own validation or its own transport\n        // error). Record why and move on — the next hop may still work.\n        chain.push(`${hop.provider.name}:failed`)\n        trace.push(...response.trace.map((entry) => `${hop.provider.name}-${entry}`))\n        continue\n      }\n\n      chain.push(`${hop.provider.name}:answered`)\n      return {\n        ...response,\n        // Degraded means \"not the first hop that was configured\". Falling to\n        // laya after an unreachable jev IS a degradation, even though laya is a\n        // real model; reaching `rule` is the loudest case.\n        degraded: hop.provider.name !== firstConfigured || response.degraded,\n        trace,\n        warnings,\n        chain,\n        latencyMs: this.deps.now() - started,\n      }\n    }\n\n    const refused = await new RefuseJudgeProvider(trace).decide(req, this.deps)\n    chain.push('refuse:terminal')\n    return { ...refused, warnings: [...warnings, ...refused.warnings], chain, latencyMs: this.deps.now() - started }\n  }\n}\n\n// ── tools ──────────────────────────────────────────────────────────────────\n\nfunction refuse(provider: ProviderName, started: number, ended: number, reasons: string[]): JudgeResponse {\n  return {\n    answers: {},\n    provider: 'refuse',\n    model: '',\n    latencyMs: Math.max(0, ended - started),\n    degraded: true,\n    trace: reasons,\n    warnings: [],\n    dropped: [],\n    missing: [],\n    // Note the asymmetry: `provider:'refuse'` travels with the reasons, so the\n    // chain above can tell a local rejection from a genuine answer.\n  }\n}\n\nfunction messageOf(error: unknown): string {\n  if (error instanceof Error) return error.message\n  return String(error)\n}\n"
    },
    {
      "path": "src/cdp/capabilities.ts",
      "content": "/**\n * src/cdp/capabilities.ts — engine detection + capability projection.\n *\n * The single point of decision for \"what can this CDP endpoint do\". The engine\n * is recognized once per probe/attach from `/json/version`'s `Browser` field;\n * every consumer (enable-domain filtering, screenshot format, capture / pick /\n * download gates) reads the projection instead of catching UnknownMethod or\n * -32000 errors after the fact.\n *\n * Zero I/O: pure functions over the discovery string, fixture-testable with no\n * socket and no clock (same discipline as events.ts).\n *\n * Degradation discipline: an UNRECOGNIZED endpoint keeps FULL capabilities —\n * misidentification must only ever withhold, never invent. Recognition only\n * ever downgrades.\n */\n\nexport type EngineId = 'chrome' | 'lightpanda' | 'tabbit' | 'unknown'\n\n/**\n * Recognize the engine from `/json/version`'s `Browser` field\n * (`\"Lightpanda/0.4.1\"`, `\"Chrome/153.0.0.0\"`, `\"Edg/153.0.0.0\"`, …).\n * Empty or unrecognized → `'unknown'` (never guesses).\n */\nexport function engineOf(browserField: string): EngineId {\n  const value = typeof browserField === 'string' ? browserField.trim() : ''\n  if (value === '') return 'unknown'\n  if (value.startsWith('Lightpanda/')) return 'lightpanda'\n  if (value.startsWith('Chrome/') || value.startsWith('Chromium')) return 'chrome'\n  if (value.startsWith('Edg/') || value.startsWith('Microsoft Edge ')) return 'chrome'\n  return 'unknown'\n}\n\nexport interface BackendCapabilities {\n  engine: EngineId\n  /** `Page.startScreencast` / `screencastFrame` exist (live view). */\n  screencast: boolean\n  /** The `Overlay` domain exists (pick highlight, inspect mode, marks). */\n  overlay: boolean\n  /** `Runtime.bindingCalled` fires after `addBinding` (pick event path). */\n  bindingCalled: boolean\n  /** The only wire format `Page.captureScreenshot` accepts. */\n  imageFormat: 'jpeg' | 'png'\n  /** `Page.loadEventFired` fires (false → `Page.lifecycleEvent name=\"load\"` instead). */\n  loadEvent: boolean\n  /** `Page.downloadWillBegin` / `downloadProgress` fire (bcdp_download). */\n  downloadEvents: boolean\n  /**\n   * Documentation bit: whether sending `Browser.close` to this endpoint would\n   * be meaningful. The plugin NEVER closes the target browser over CDP today\n   * (managed stop is killTree; remote stop is WS close). The one `Browser.close`\n   * call site (login-import's temp Chrome) targets a LOCALLY spawned process\n   * and must not consult this flag — see the regression note there.\n   */\n  browserClose: boolean\n}\n\nconst FULL: BackendCapabilities = {\n  engine: 'chrome',\n  screencast: true,\n  overlay: true,\n  bindingCalled: true,\n  imageFormat: 'jpeg',\n  loadEvent: true,\n  downloadEvents: true,\n  browserClose: true,\n}\n\n/**\n * The capability projection per engine. `chrome` / `unknown` → full\n * capabilities (bit-for-bit today's behavior); `lightpanda` → the analysis\n * (docs/plans/2026-10-04-lightpanda-backend-analysis.md §7) projection;\n * `tabbit` → CLI-protocol limitations (no download events, no overlay pick,\n * no raw CDP screencast through the plugin's usual path).\n */\nexport function capabilitiesFor(engine: EngineId): BackendCapabilities {\n  if (engine === 'lightpanda') {\n    return {\n      engine: 'lightpanda',\n      screencast: false, // no screencast methods at all\n      overlay: false, // no Overlay domain (UnknownMethod on enable)\n      bindingCalled: false, // addBinding exists, the event never fires\n      imageFormat: 'png', // captureScreenshot rejects other formats (-32000)\n      loadEvent: false, // lifecycleEvent(load) replaces loadEventFired\n      downloadEvents: false, // no downloadWillBegin / downloadProgress\n      browserClose: false,\n    }\n  }\n  if (engine === 'tabbit') {\n    // Tabbit browser IS Chromium (CDP fully present), but the tabbit-cli\n    // connection model restricts what the plugin can reach:\n    //   - Browser.* and Target.* domains rejected (no tab enumeration)\n    //   - Playwright download events unavailable (connection-mode limit)\n    //   - Overlay/bindingCalled work only via newCDPSession (page-scoped)\n    //   - Screencast available (Page domain allowed) but needs 2nd CDP session\n    // The plugin gate uses these flags to skip tools that would hang/fail.\n    return {\n      engine: 'tabbit',\n      screencast: true,       // Page.startScreencast allowed via newCDPSession\n      overlay: false,         // Overlay domain works but plugin pick path needs Browser.*\n      bindingCalled: false,   // Runtime.addBinding not reliably reachable\n      imageFormat: 'jpeg',    // Tabbit is Chromium, jpeg native\n      loadEvent: true,        // Playwright handles load waiting\n      downloadEvents: false,  // SKILL.md: \"download events unavailable\"\n      browserClose: false,    // Browser.* rejected\n    }\n  }\n  return { ...FULL, engine }\n}\n\n/** Convenience: project straight from a discovery `Browser` string. */\nexport function capabilitiesForBrowser(browserField: string): BackendCapabilities {\n  return capabilitiesFor(engineOf(browserField))\n}\n\n/**\n * Env key the host half sets when spawning the cast / render workers\n * (mirrors `EGO_LINUX_CDP_URL`'s injection pattern in cast-server). The child\n * processes cannot see the host's attach cache, so the projected engine id\n * travels as data — the host decides once, children only read.\n */\nexport const BCDP_CDP_ENGINE = 'BCDP_CDP_ENGINE'\n\n/**\n * Project capabilities from the spawn-env value. Anything absent or\n * unrecognized means FULL capabilities — an unknown engine must never\n * conservatively break a Chrome endpoint.\n */\nexport function capabilitiesFromEnvValue(value: string | undefined): BackendCapabilities {\n  const v = (value ?? '').trim()\n  if (v === 'lightpanda') return capabilitiesFor('lightpanda')\n  if (v === 'tabbit') return capabilitiesFor('tabbit')\n  return capabilitiesFor('unknown')\n}\n"
    }
